  dispose3d() {
    const d = this._3d;
    if (!d) return;
    cancelAnimationFrame(d.raf);
    if (d.ro) d.ro.disconnect();
    d.canvas.removeEventListener('pointermove', d.onMove);
    d.canvas.removeEventListener('pointerleave', d.onLeave);
    d.scene.traverse((o) => {
      if (o.geometry) o.geometry.dispose();
      if (o.material) o.material.dispose();
    });
    d.renderer.dispose();
    this._3d = null;
  }

