    cuc.rotation.z = Math.PI / 2;
    for (let i = 0; i < 5; i++) { const sl = cyl(0.06, 0.06, 0.02, mat(0xb7d77a), TX - 0.12 + i * 0.05, 1.0, TZ + 0.18); sl.rotation.z = Math.PI / 2 + 0.3; }
    ball(0.12, mat(0xe5322d, { roughness: 0.3 }), TX + 0.12, 1.06, TZ + 0.3, 1, 0.85, 1);
    const knife = new THREE.Group();
    add(new THREE.Mesh(new THREE.BoxGeometry(0.42, 0.08, 0.012), mat(0xe8ebf3, { metalness: 0.85, roughness: 0.2 })), 0.29, 0, 0, knife);
    add(new THREE.Mesh(new THREE.BoxGeometry(0.16, 0.05, 0.035), blackM), 0.02, 0.01, 0, knife);
    knife.position.set(TX - 0.08, 1.03, TZ + 0.06);
    knife.rotation.y = Math.PI;
    kitchen.add(knife);
    const bowl = new THREE.Mesh(new THREE.SphereGeometry(0.3, 28, 14, 0, Math.PI * 2, Math.PI / 2, Math.PI / 2), mat(0xffffff, { roughness: 0.3, side: THREE.DoubleSide }));
    add(bowl, TX + 0.25, 1.24, TZ - 0.3);
    [[0, 0], [0.1, 0.06], [-0.1, 0.05], [0.05, -0.1], [-0.06, -0.08]].forEach(([dx, dz]) => ball(0.1, mat(0x5cae4a, { roughness: 0.8 }), TX + 0.25 + dx, 1.22, TZ - 0.3 + dz, 1, 0.6, 1));
    [[0.08, 0.02], [-0.07, -0.03], [0.0, 0.09]].forEach(([dx, dz]) => ball(0.045, mat(0xe5322d), TX + 0.25 + dx, 1.28, TZ - 0.3 + dz));
    [[0, 0], [0.12, 0.05], [-0.1, 0.06], [0.03, 0.13]].forEach(([dx, dz]) => ball(0.12, mat(0x7cc35a, { roughness: 0.85 }), TX - 0.35 + dx, 1.05, TZ - 0.3 + dz));
    ball(0.11, mat(0xf2b01e, { roughness: 0.4 }), TX + 0.45, 1.03, TZ + 0.3, 0.9, 1.1, 0.9);

    const reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    let target = 0, cur = 0;
    const onMove = (e) => { const r = canvas.getBoundingClientRect(); target = ((e.clientX - r.left) / r.width - 0.5) * 1.2; };
    const onLeave = () => { target = 0; };
    canvas.addEventListener('pointermove', onMove);
    canvas.addEventListener('pointerleave', onLeave);
    const fit = () => {
      const w = canvas.clientWidth, h = canvas.clientHeight;
      if (!w || !h) return;
      renderer.setSize(w, h, false);
      camera.aspect = w / h;
      const k = Math.max(1, 1.62 / camera.aspect);
      camera.position.set(0.45, 3.7 * k, 8.4 * k);
      camera.lookAt(0.45, 1.2, -0.75);
      camera.updateProjectionMatrix();
    };
    const ro = window.ResizeObserver ? new ResizeObserver(fit) : null;
    if (ro) ro.observe(canvas);
    fit();

    const start = performance.now();
    const d = { renderer, scene, canvas, ro, onMove, onLeave, raf: 0 };
    this._3d = d;
    const frame = () => {
      const t = reduce ? 1.3 : (performance.now() - start) / 1000;
      cur += (target - cur) * 0.06;
      kitchen.rotation.y = -0.12 + (reduce ? 0 : Math.sin(t * 0.25) * 0.12) + cur * 0.5;
      steam.forEach((s) => {
        const life = ((t * s.speed + s.phase) % 1 + 1) % 1;
        s.p.position.set(s.x + Math.sin(life * 6 + s.phase * 10) * s.spread * life, s.y + life * s.height, s.z + Math.cos(life * 5 + s.phase * 7) * s.spread * 0.5 * life);
        s.p.scale.setScalar(s.size * (0.45 + life * 2.3));
        s.p.material.opacity = Math.sin(Math.PI * life) * 0.3;
      });
      flames.forEach(({ f, i }) => { f.scale.y = 0.75 + 0.35 * Math.abs(Math.sin(t * 18 + i * 1.7)); });
      embers.forEach(({ e, i }) => { e.material.emissiveIntensity = 0.7 + 0.8 * Math.abs(Math.sin(t * 2.4 + i * 0.9)); });
      bobs.forEach((b) => { b.m.position.y = b.y + Math.abs(Math.sin(t * b.f)) * b.amp; });
      knife.rotation.z = -Math.abs(Math.sin(t * 5)) * 0.55;
      renderer.render(scene, camera);
    };
    const loop = () => {
      d.raf = requestAnimationFrame(loop);
      if (this.state.splash) frame();
    };
    if (reduce) frame(); else loop();
  }

  item(id) { return this.ITEMS.find((i) => i.id === id); }
  kitchen(id) { return this.KITCHENS.find((k) => k.id === id); }
  // סכום שלילי (הפסד) מוצג כ-‎-₪5 ולא ₪-5
  money(n) { const r = Math.round(n); return (r < 0 ? '-' : '') + '₪' + Math.abs(r).toLocaleString('he-IL'); }
  money2(n) { const t = Math.abs(n).toFixed(2); return (n < 0 && +t !== 0 ? '-' : '') + '₪' + t; }
  // צבע לרווח: אדום בהפסד
  plStyle(n, extra) { return (extra || '') + (n < 0 ? 'color: #C62F4A' : 'color: #037F4C'); }
  pct(x) { return (isFinite(x) ? x * 100 : 0).toFixed(1) + '%'; }
  bar(p, color) { return 'height:100%;border-radius:6px;background:' + color + ';width:' + Math.max(2, Math.min(100, p)).toFixed(1) + '%'; }
  fcCls(fc) { return fc <= 0.3 ? 'pill p-ok' : fc <= 0.35 ? 'pill p-low' : 'pill p-bad'; }
  fmtQty(n, it) { return (it.unit === 'יח׳' ? Math.ceil(n) : Math.round(n * 10) / 10) + ' ' + it.unit; }

  isUnit(it) { return it.unit === 'יח׳'; }
  amtLabel(it) { return this.isUnit(it) ? 'יח׳' : it.unit === 'ליטר' ? 'מ״ל' : 'גרם'; }
  toBase(it, amt) { return this.isUnit(it) ? amt : amt / 1000; }

  /* מנות: הכול נגזר מהתפריט השבועי (state.wm), מהמתכונים (state.mrec) ומחיר הארוחה (state.mealPrice).
     m הוא תפריט (stu / stf). aud הוא סינון: all, או תפריט אחד */
  recOf(name) { return this.state.mrec[String(name).trim()] || null; }
  mealPrice(m) {
    const p = this.state.mealPrice;
    if (m === 'stf') return p.stf !== undefined ? p.stf : Math.round(p.stu * this.STAFF_RATE * 100) / 100;
    return p.stu || 0;
  }
  staffAuto() { return this.state.mealPrice.stf === undefined; }
  // הרכיב בארוחה: מנה עיקרית, ירקות (שורה עם "ירק" או "סלט"), וכל השאר פחמימה
  rowPart(r) { return this.isMainRow(r) ? 'main' : /ירק|סלט/.test(r.slot) ? 'veg' : 'carb'; }
  partLabel(p) { return (this.PARTS.find((x) => x[0] === p) || [])[1] || ''; }
  // יעד עלות למנה לפי הרכיב שלה בגיליון, בסיס ופסימי
  partTarget(p) { const b = this.SHEET.parts[p] || 0; return { base: b, pess: b * (1 + this.SHEET.pess) }; }
  targetLvl(cost, p) { const t = this.partTarget(p); return !t.base ? '' : cost > t.pess ? 'red' : cost > t.base ? 'orange' : ''; }
  menuIds(aud) { return !aud || aud === 'all' ? this.MENUS.map((x) => x.id) : [aud]; }
  menuLabel(m) { return (this.MENUS.find((x) => x.id === m) || {}).label || ''; }
  rowsOf(m) { return this.state.wm.menus[m] || []; }
  // התפריטים שמנה מופיעה בהם
  dishMenus(name) { return this.MENUS.map((x) => x.id).filter((m) => this.rowsOf(m).some((r) => r.cells.some((c) => c.trim() === name))); }

  dishCost(name) {
    return (this.recOf(name) || []).reduce((a, l) => {
      const it = this.item(l.id);
      return a + this.toBase(it, l.amt) * it.price;
    }, 0);
  }

  // כל המנות שבתפריטים, לפי סדר ההופעה
  menuDishes(aud) {
    const out = [];
    this.menuIds(aud).forEach((m) => this.rowsOf(m).forEach((r) => r.cells.forEach((c) => { const n = c.trim(); if (n && out.indexOf(n) < 0) out.push(n); })));
    return out;
  }

  // מנה עיקרית: "מנה עיקרית ..." או "מנת בשר". הסועדים מתחלקים בין המנות העיקריות
  isMainRow(r) { return /^(מנה עיקרית|מנת בשר)/.test(r.slot.trim()); }

  // מנות מתוכננות לשורה ביום: מספר הסועדים של התפריט, ובמנות עיקריות הוא מתחלק בין השורות. כמות שהוזנה ידנית גוברת
  planPortions(m, r, di) {
    const s = this.state;
    const o = s.wmPortions[r.id + '_' + di];
    if (o !== undefined && o !== '') return this.intVal(o);
    if (!r.cells[di].trim()) return 0;
    const D = this.intVal(s.wmDiners[m][di]);
    if (!this.isMainRow(r)) return D;
    const mains = this.rowsOf(m).filter((x) => this.isMainRow(x) && x.cells[di].trim()), i = mains.indexOf(r);
    return mains.length > 1 ? Math.floor(D / mains.length) + (i >= 0 && i < D % mains.length ? 1 : 0) : D;
  }

  // המנות של עמודה בתפריט השבועי, בתפריטים שבסינון
  dayDishes(col, aud) {
    const out = [];
    this.menuIds(aud).forEach((m) => this.rowsOf(m).forEach((r) => {
      const name = r.cells[col] ? r.cells[col].trim() : '';
      if (!name) return;
      out.push({ key: r.id + '|' + name, menu: m, menuLabel: this.menuLabel(m), name, slot: r.slot, main: this.isMainRow(r), part: this.rowPart(r), planned: this.planPortions(m, r, col) });
    }));
    return out;
  }

  seed(str) { let h = 2166136261; for (let i = 0; i < str.length; i++) { h ^= str.charCodeAt(i); h = Math.imul(h, 16777619) >>> 0; } return h; }

  // ייצור לפי יום: d הוא אינדקס ב-HISTDAYS. ימים קודמים הם נתוני דוגמה שנגזרים מהתפריט; היום מגיע מהדיווח היומי
  dayProd(k, d, aud) {
    const today = d === this.HISTDAYS.length - 1;
    const rep = this.state.prod[k] || {};
    const rows = this.dayDishes(this.HISTDAYS[d].col, aud).map((x) => {
      const h = this.seed(x.menu + '|' + x.name + '|' + d), n = x.planned;
      const thrown = Math.round(n * (0.01 + (h % 1000) / 1000 * 0.05));
      const left = Math.round(n * ((h >>> 10) % 1000) / 1000 * 0.12);
      return Object.assign({}, x, { out: n, left, thrown });
    });
    // מקדם עלות לכל תפריט: עלות המתכונים של הייצור המתוכנן מכוילת כך שתהיה בדיוק עלות לארוחה × סועדים
    const col = this.HISTDAYS[d].col, scale = {};
    this.MENUS.forEach((mm) => {
      const mr = rows.filter((r) => r.menu === mm.id);
      if (!mr.length) return;
      const meals = this.intVal(this.state.wmDiners[mm.id][col]);
      const raw = mr.reduce((a, r) => a + (r.out + r.left + r.thrown) * this.dishCost(r.name), 0) + meals * this.SHEET.parts.sauce;
      scale[mm.id] = raw ? meals * this.MEAL_COST[mm.id] / raw : 0;
    });
    const live = rows.map((row) => { const o = today && rep[row.key]; return o ? Object.assign({}, row, o) : row; });
    return this.allocate(live, col, scale);
  }

  // מחיר ממוצע לארוחה ביום מסוים. עובדי מטה: לפי התמהיל של 23 ו-60 באותו יום בשבוע
  dayMealPrice(m, col) {
    if (m !== 'stf') return this.mealPrice(m);
    const x = this.STAFF_MIX[col], n = x.low + x.high;
    return n ? (x.low * this.STAFF_PRICES.low + x.high * this.STAFF_PRICES.high) / n : 0;
  }

  // ארוחות שנמכרו = מנות עיקריות שיצאו. ההכנסה (ארוחות × מחיר ארוחה) מתחלקת בין הרכיבים לפי משקלי הגיליון,
  // ובתוך כל רכיב לפי מספר המנות שיצאו. רטבים ותבלינים הם שורה נפרדת: חלק מההכנסה, ועלות קבועה לארוחה מהגיליון
  allocate(rows, col, scale) {
    const out = [];
    this.MENUS.forEach((mm) => {
      const mr = rows.filter((r) => r.menu === mm.id);
      if (!mr.length) return;
      const mains = mr.filter((r) => r.part === 'main');
      const meals = mains.length ? mains.reduce((a, r) => a + r.out, 0) : Math.max(...mr.map((r) => r.out));
      const rev = meals * this.dayMealPrice(mm.id, col), f = scale[mm.id] || 0;
      const present = ['main', 'carb', 'veg'].filter((p) => mr.some((r) => r.part === p)).concat(['sauce']);
      const W = present.reduce((a, p) => a + this.SHEET.parts[p], 0);
      present.forEach((p) => {
        const share = rev * this.SHEET.parts[p] / W;
        if (p === 'sauce') {
          out.push({ key: mm.id + '|sauce', menu: mm.id, menuLabel: mm.label, name: 'רטבים ותבלינים', slot: 'רטבים ותבלינים', main: false, part: 'sauce', virtual: true,
            planned: meals, out: meals, left: 0, thrown: 0, rev: share, unit: this.SHEET.parts.sauce * f });
          return;
        }
        const pr = mr.filter((r) => r.part === p), sumOut = pr.reduce((a, r) => a + r.out, 0);
        pr.forEach((r) => { out.push(Object.assign({}, r, { rev: sumOut ? share * r.out / sumOut : 0, unit: this.dishCost(r.name) * f })); });
      });
    });
    return out;
  }

  // ממוצעים לארוחה בתפריט, לפי חמשת ימי העבודה האחרונים: הכנסה, ועלות חומרי גלם לכל רכיב
  mealStats(m) {
    const kIds = this.KITCHENS.map((x) => x.id);
    const parts = { main: 0, carb: 0, veg: 0, sauce: 0 };
    let meals = 0, rev = 0;
    kIds.forEach((k) => this.HISTDAYS.forEach((h, d) => this.dayProd(k, d, m).forEach((r) => {
      const unit = r.unit !== undefined ? r.unit : this.dishCost(r.name);
      parts[r.part] += (r.out + r.left + r.thrown) * unit;
      rev += r.rev;
      if (r.part === 'main') meals += r.out;
    })));
    const per = {};
    Object.keys(parts).forEach((p) => { per[p] = meals ? parts[p] / meals : 0; });
    const food = per.main + per.carb + per.veg + per.sauce;
    return { meals, rev, revPerMeal: meals ? rev / meals : 0, per, food };
  }

  // סיכום לפי מנה לתקופה: יום = היום, שבוע = חמשת ימי העבודה האחרונים, חודש = השבוע מוכפל לפי ימי העבודה
  // מנה שמופיעה בשני התפריטים מסוכמת לשורה אחת. ההכנסה מחושבת לפי המחיר של כל תפריט
  periodAgg(kIds, period, aud, day) {
    const days = period === 'day' ? [day !== undefined ? day : this.HISTDAYS.length - 1] : this.HISTDAYS.map((x, i) => i);
    const mult = period === 'month' ? this.MONTH_DAYS / this.HISTDAYS.length : 1;
    const agg = {}, order = [];
    kIds.forEach((k) => days.forEach((d) => this.dayProd(k, d, aud).forEach((r) => {
      if (!agg[r.name]) { agg[r.name] = { name: r.name, main: r.main, part: r.part, virtual: !!r.virtual, out: 0, left: 0, thrown: 0, rev: 0, cost: 0, menus: [] }; order.push(r.name); }
      const a = agg[r.name];
      a.main = a.main || r.main; a.out += r.out; a.left += r.left; a.thrown += r.thrown;
      a.rev += r.rev; a.cost += (r.out + r.left + r.thrown) * r.unit;
      if (a.menus.indexOf(r.menu) < 0) a.menus.push(r.menu);
    })));
    // סדר השורות כמו בתפריט השבועי
    // רטבים ותבלינים בסוף
    const pos = this.menuDishes(aud), at = (n) => pos.indexOf(n) < 0 ? 1e6 : pos.indexOf(n);
    order.sort((a, b) => at(a) - at(b));
    return order.map((n) => {
      const a = agg[n];
      const out = Math.round(a.out * mult), left = Math.round(a.left * mult), thrown = Math.round(a.thrown * mult);
      const prep = a.out + a.left + a.thrown;
      return { name: n, main: a.main, part: a.part, virtual: a.virtual, out, left, thrown, prepared: out + left + thrown, rev: a.rev * mult, cost: a.cost * mult, menus: a.menus, unit: prep ? a.cost / prep : 0 };
    });
  }

  rawWasteCost(k) { return this.state.rawWaste[k].reduce((a, w) => a + w.amt * this.item(w.id).price, 0); }

  netPrice(p) { return this.state.vatIn ? p / (1 + this.VAT) : p; }

  pmNum(v) { const n = parseFloat(v); return isFinite(n) && n > 0 ? n : 0; }

  fullCost(food) {
    const p = this.state.pm;
    const perDay = Math.max(1, this.pmNum(p.perDay));
    const pack = this.pmNum(p.pack), energy = this.pmNum(p.energy), app = this.pmNum(p.app);
    const laborDay = this.pmNum(p.salary) / Math.max(1, this.pmNum(p.workDays)) * this.pmNum(p.hours) / 8;
    const fixedDay = this.pmNum(p.dist) / Math.max(1, this.pmNum(p.days)) + laborDay;
    const dist = this.pmNum(p.dist) / (perDay * Math.max(1, this.pmNum(p.days)));
    const labor = laborDay / perDay;
    const variable = food + pack + energy + app;
    return { food, pack, energy, app, dist, labor, variable, fixedDay, total: variable + dist + labor };
  }

  stock(q, min) {
    if (q === 0) return { key: 'out', label: 'חסר', cls: 'pill p-bad' };
    if (q < min) return { key: 'low', label: 'נמוך', cls: 'pill p-low' };
    return { key: 'ok', label: 'תקין', cls: 'pill p-ok' };
  }

  daysLeft(it, k) { return it.exp - this.kitchen(k).off; }

  dateFrom(d) {
    const dt = new Date(2026, 9, 22 + d);
    return String(dt.getDate()).padStart(2, '0') + '.' + String(dt.getMonth() + 1).padStart(2, '0') + '.' + dt.getFullYear();
  }

  // סיכום כספי למטבח לתקופה. פחת חומרי הגלם נרשם ליום, ובשבוע ובחודש הוא מוכפל במספר ימי העבודה.
  // פחת חומרי גלם לא שייך לתפריט מסוים, ולכן הוא נכלל רק כשמוצגים שני התפריטים
  prodTotals(k, period, aud, day) {
    period = period || 'day';
    let out = 0, left = 0, thrown = 0, rev = 0, cost = 0, waste = 0;
    this.periodAgg([k], period, aud, day).forEach((x) => {
      if (!x.virtual) { out += x.out; left += x.left; thrown += x.thrown; }
      rev += x.rev;
      cost += x.cost;
      waste += x.thrown * x.unit;
    });
    const dishWaste = waste;
    const rawCost = !aud || aud === 'all' ? this.rawWasteCost(k) * { day: 1, week: this.HISTDAYS.length, month: this.MONTH_DAYS }[period] : 0;
    waste += rawCost;
    return { out, left, thrown, rev, cost, waste, dishWaste, rawCost };
  }

  /* השוואת רווח והפסד לפי שבועות ולפי חודשים.
     התקופה האחרונה מחושבת מהנתונים החיים. התקופות הקודמות הן נתוני דוגמה: בסיס שנקבע בטעינה, כפול מקדם לכל תקופה.
     כך שינוי בתפריט או במחירים משנה רק את התקופה הנוכחית, ומופיעה ירידה אמיתית מול העבר */
  trendBase() {
    if (this._trendBase) return this._trendBase;
    const kIds = this.KITCHENS.map((x) => x.id);
    const base = {};
    ['week', 'month'].forEach((type) => {
      base[type] = { raw: kIds.reduce((a, k) => a + this.prodTotals(k, type, 'all').rawCost, 0) };
      this.MENUS.forEach((mm) => {
        let rev = 0, cost = 0;
        kIds.forEach((k) => { const t = this.prodTotals(k, type, mm.id); rev += t.rev; cost += t.cost; });
        base[type][mm.id] = { rev, cost };
      });
    });
    return (this._trendBase = base);
  }

  trendPeriods(type) {
    const out = [];
    if (type === 'week') {
      // שבוע = ראשון עד חמישי, כמו הדוח השבועי. האחרון מסתיים היום, 22.10
      const dd = (d) => String(d.getDate()).padStart(2, '0') + '.' + String(d.getMonth() + 1).padStart(2, '0');
      for (let i = this.TREND_N.week - 1; i >= 0; i--) {
        const end = new Date(2026, 9, 22 - i * 7), start = new Date(2026, 9, 22 - i * 7 - 4);
        out.push({ short: dd(end), label: dd(start) + '–' + dd(end) });
      }
    } else {
      const names = ['מרץ', 'אפריל', 'מאי', 'יוני', 'יולי', 'אוגוסט', 'ספטמבר', 'אוקטובר'];
      names.forEach((n, i) => out.push({ short: i === names.length - 1 ? 'אוק׳ (צפי)' : n, label: n + ' 2026' + (i === names.length - 1 ? ' · צפי לפי השבוע האחרון' : '') }));
    }
    return out;
  }

  trendFactor(type, i, m) {
    const h = this.seed(type + '|' + m + '|' + i);
    let r = 1 + ((h % 1000) / 1000 - 0.5) * 0.08;
    let c = r * (1 + (((h >>> 10) % 1000) / 1000 - 0.5) * 0.06);
    const e = (this.TREND_EVENTS[type][i] || {})[m];
    if (e) { r *= e.r || 1; c *= e.c || 1; }
    return { r, c };
  }

  // שורות לגרף ולטבלה: הכנסה, עלות, רווח גולמי, ושינוי מול ממוצע 4 התקופות הקודמות
  trendRows(type, aud) {
    const base = this.trendBase()[type], ms = this.menuIds(aud), n = this.TREND_N[type];
    const kIds = this.KITCHENS.map((x) => x.id);
    const per = this.trendPeriods(type);
    const rows = per.map((p, i) => {
      let rev = 0, cost = 0;
      if (i === n - 1) {
        kIds.forEach((k) => { const t = this.prodTotals(k, type, aud); rev += t.rev; cost += t.cost; });
      } else {
        ms.forEach((m) => { const f = this.trendFactor(type, i, m); rev += base[m].rev * f.r; cost += base[m].cost * f.c; });
      }
      return { i, short: p.short, label: p.label, current: i === n - 1, rev, cost, profit: rev - cost };
    });
    const lvl = (drop) => drop > this.DROP_RED ? 'red' : drop > this.DROP_ORANGE ? 'orange' : '';
    rows.forEach((r, i) => {
      if (i < 4) return;
      const prev = rows.slice(i - 4, i);
      const avgRev = prev.reduce((a, x) => a + x.rev, 0) / 4, avgProfit = prev.reduce((a, x) => a + x.profit, 0) / 4;
      r.revChg = avgRev ? r.rev / avgRev - 1 : 0;
      r.profitChg = avgProfit > 0 ? r.profit / avgProfit - 1 : undefined;
      r.revLvl = lvl(-r.revChg);
      r.profitLvl = lvl(-r.profitChg);
      r.lvl = r.revLvl === 'red' || r.profitLvl === 'red' ? 'red' : r.revLvl || r.profitLvl ? 'orange' : '';
    });
    return rows;
  }

  // התראות על התקופה הנוכחית: כל המטבח, וכל תפריט בנפרד. הכנסה ורווח גולמי, כל אחד בנפרד
  plAlerts() {
    const out = [];
    ['week', 'month'].forEach((type) => ['all'].concat(this.MENUS.map((x) => x.id)).forEach((aud) => {
      const rows = this.trendRows(type, aud), cur = rows[rows.length - 1];
      [['rev', 'ההכנסה', 'ירידה בהכנסה'], ['profit', 'הרווח הגולמי', 'ירידה ברווח']].forEach(([f, name, tag]) => {
        const l = cur[f + 'Lvl'];
        if (!l) return;
        const who = aud === 'all' ? 'של כל המטבח' : 'של תפריט ה' + this.menuLabel(aud);
        const span = type === 'week' ? 'השבוע (' + cur.label + ') לעומת ממוצע 4 השבועות הקודמים' : 'בצפי לחודש ' + cur.label.split(' ')[0] + ' לעומת ממוצע 4 החודשים הקודמים';
        out.push({
          key: 'pl:' + type + ':' + aud + ':' + f, type, aud, level: l, metric: f,
          tag: (l === 'red' ? 'קריטי · ' : '') + tag, cls: l === 'red' ? 'pill p-bad' : 'pill p-low',
          text: f === 'profit' && cur.profit < 0
            ? name + ' ' + who + ' עבר להפסד של ' + this.money(-cur.profit) + ' ' + span + '.'
            : name + ' ' + who + ' ירד' + (f === 'profit' ? '' : 'ה') + ' ב-' + this.pct(-cur[f + 'Chg']) + ' ' + span + '.',
          where: 'דוחות · ' + (type === 'week' ? 'שבועי' : 'חודשי') + ' · ' + (aud === 'all' ? 'הכול' : this.menuLabel(aud))
        });
      });
    }));
    // קריטי קודם
    return out.sort((a, b) => (a.level === 'red' ? 0 : 1) - (b.level === 'red' ? 0 : 1));
  }

  // גרף עמודות מוערמות: עלות חומרי גלם (אפור) ורווח גולמי (כחול). גובה העמודה = הכנסה. הזמן משמאל לימין: העדכני מימין
  trendChart(rows, type, hoverKey, view) {
    // בתצוגת קו יש מקום משמאל לתוויות שליד הנקודה האחרונה
    const isLine = view === 'line';
    const W = 720, L = 56, R = isLine ? 592 : 708, T = 34, B = 226;
    const n = rows.length, slot = (R - L) / n, bw = Math.min(34, slot * 0.56);
    const maxV = Math.max(1, ...rows.map((r) => Math.max(r.rev, r.cost)));
    const raw = maxV / 4, p10 = Math.pow(10, Math.floor(Math.log10(raw)));
    const step = [1, 2, 2.5, 5, 10].map((k) => k * p10).find((v) => v >= raw);
    const top = step * 4;
    const y = (v) => B - Math.max(0, v) / top * (B - T);
    const fmtK = (v) => v >= 1000 ? (v / 1000).toLocaleString('he-IL', { maximumFractionDigits: 1 }) + 'K' : String(Math.round(v));
    const roundTop = (x, yt, w, yb, r) => {
      r = Math.max(0, Math.min(r, (yb - yt) / 2, w / 2));
      return 'M' + x + ',' + yb + 'L' + x + ',' + (yt + r) + 'Q' + x + ',' + yt + ' ' + (x + r) + ',' + yt + 'L' + (x + w - r) + ',' + yt + 'Q' + (x + w) + ',' + yt + ' ' + (x + w) + ',' + (yt + r) + 'L' + (x + w) + ',' + yb + 'Z';
    };
    const ticks = [0, 1, 2, 3, 4].map((k) => ({ key: k, y: y(step * k), ty: y(step * k) + 4, label: '₪' + fmtK(step * k), x1: L, x2: R, tx: L - 8 }));
    const bars = rows.map((r, i) => {
      const cx = L + (i + 0.5) * slot, x = cx - bw / 2;
      const yc = y(r.cost), yr = y(r.rev), hasProfit = r.profit > 0 && yc - yr > 3;
      const key = type + ':' + i, hot = hoverKey === key;
      const flagW = 44;
      return {
        key: i, hot,
        band: !!r.lvl || hot, bandX: cx - slot / 2 + 1, bandY: T - 26, bandW: slot - 2, bandH: B - T + 26,
        bandFill: r.lvl === 'red' ? '#FDECEF' : r.lvl === 'orange' ? '#FFF4E5' : '#F3F4F8',
        cost: hasProfit ? 'M' + x + ',' + B + 'L' + x + ',' + (yc + 1) + 'L' + (x + bw) + ',' + (yc + 1) + 'L' + (x + bw) + ',' + B + 'Z' : roundTop(x, yc, bw, B, 4),
        profit: hasProfit ? roundTop(x, yr, bw, yc - 1, 4) : '',
        hasProfit,
        lx: cx, ly: B + 17, label: r.short, labelW: r.current ? '700' : '400',
        flag: !!r.lvl, flagX: cx - flagW / 2, flagY: yr - 26, flagW, flagFill: r.lvl === 'red' ? '#C62F4A' : '#FDAB3D', flagInk: r.lvl === 'red' ? '#FFFFFF' : '#22253A',
        flagText: !r.lvl ? '' : Math.max(-(r.revChg || 0), -(r.profitChg || 0)) >= 1 ? '▼ הפסד' : '▼ ' + Math.round(Math.max(-(r.revChg || 0), -(r.profitChg || 0)) * 100) + '%', flagTx: cx, flagTy: yr - 13,
        value: r.current && !isLine, valueText: '₪' + fmtK(r.rev), valueY: r.lvl ? yr - 32 : yr - 8,
        hitX: cx - slot / 2, hitY: T - 26, hitW: slot, hitH: B - T + 46,
        enter: () => this.setState({ trendHover: key }),
        leave: () => this.setState((st) => (st.trendHover === key ? { trendHover: null } : null))
      };
    });
    const h = rows.find((r, i) => hoverKey === type + ':' + i);
    let tip = null;
    if (h) {
      const cx = L + (h.i + 0.5) * slot;
      const chg = (v, l) => v === undefined ? '' : (v <= -1 ? '▼ עבר להפסד' : (v < 0 ? '▼ ' : '▲ ') + this.pct(Math.abs(v))) + (l === 'red' ? ' · קריטי' : l === 'orange' ? ' · התראה' : '');
      tip = {
        // החלונית ליד העמודה ולא עליה, כדי שהעמודה והסימון שלה יישארו גלויים
        style: cx > W / 2 ? 'left: ' + ((cx - slot / 2) / W * 100).toFixed(2) + '%; transform: translateX(-100%)' : 'left: ' + ((cx + slot / 2) / W * 100).toFixed(2) + '%; transform: none',
        title: h.label, rev: this.money(h.rev), cost: this.money(h.cost), profit: this.money(h.profit), profitStyle: this.plStyle(h.profit),
        hasChg: h.revChg !== undefined, revChg: chg(h.revChg, h.revLvl), profitChg: chg(h.profitChg, h.profitLvl),
        // אחוזים שמופיעים בכל עמודה: שיעור רווח, עלות מזון, ושינוי מול התקופה הקודמת
        margin: h.rev ? this.pct(h.profit / h.rev) : '—', foodPct: h.rev ? this.pct(h.cost / h.rev) : '—',
        hasPrev: h.i > 0,
        prevRev: h.i > 0 && rows[h.i - 1].rev ? chg(h.rev / rows[h.i - 1].rev - 1) : '',
        prevProfit: h.i > 0 && rows[h.i - 1].profit > 0 ? chg(h.profit / rows[h.i - 1].profit - 1) : ''
      };
    }
    // קווים: רווח גולמי מודגש בכחול, הכנסה ועלות באפור (עלות מקווקו). נקודה אדומה או כתומה בתקופה עם ירידה
    let lines = { paths: [], dots: [], labels: [], hasCross: false };
    const series = [
      { key: 'rev', label: 'הכנסה', color: '#6B7190', dash: '', w: 2 },
      { key: 'cost', label: 'עלות חומרי גלם', color: '#9AA0B4', dash: '6 4', w: 2 },
      { key: 'profit', label: 'רווח גולמי', color: '#3B4BD8', dash: '', w: 2.5 }
    ];
    if (isLine) {
      const pts = rows.map((r, i) => ({ r, i, x: L + (i + 0.5) * slot }));
      const statusFill = (l) => l === 'red' ? '#C62F4A' : l === 'orange' ? '#FDAB3D' : '';
      lines.paths = series.map((sr) => ({ key: sr.key, d: pts.map((p, k) => (k ? 'L' : 'M') + p.x.toFixed(1) + ',' + y(p.r[sr.key]).toFixed(1)).join(''), stroke: sr.color, dash: sr.dash, w: sr.w }));
      pts.forEach((p) => series.forEach((sr) => {
        const l = sr.key === 'rev' ? p.r.revLvl : sr.key === 'profit' ? p.r.profitLvl : '';
        const hot = hoverKey === type + ':' + p.i;
        lines.dots.push({ key: sr.key + p.i, cx: p.x, cy: y(p.r[sr.key]), r: l ? 6 : hot ? 5 : 4, fill: statusFill(l) || sr.color });
      }));
      const cur = rows[rows.length - 1], x0 = pts[pts.length - 1].x;
      // הסכום מבודד כטקסט משמאל לימין (U+2066 ... U+2069), כדי שלא יתערבב עם התווית העברית
      const LRI = String.fromCharCode(0x2066), PDI = String.fromCharCode(0x2069);
      const labs = series.map((sr) => ({ key: sr.key, text: sr.label + ' ' + LRI + '₪' + fmtK(cur[sr.key]) + PDI, y: y(cur[sr.key]) + 4, x: x0 + 12, fill: '#22253A', weight: sr.key === 'profit' ? '700' : '400' }))
        .sort((a, b) => a.y - b.y);
      for (let k = 1; k < labs.length; k++) if (labs[k].y - labs[k - 1].y < 15) labs[k].y = labs[k - 1].y + 15;
      lines.labels = labs;
      const hp = pts.find((p) => hoverKey === type + ':' + p.i);
      if (hp) Object.assign(lines, { hasCross: true, crossX: hp.x, crossY1: T - 26, crossY2: B });
    }
    // מקרא לפי סוג הגרף
    const legend = isLine
      ? series.slice().reverse().map((sr) => ({ key: sr.key, label: sr.label, cls: 'swl', style: 'border-top: ' + (sr.key === 'profit' ? 3 : 2) + 'px ' + (sr.dash ? 'dashed ' : 'solid ') + sr.color }))
      : [{ key: 'profit', label: 'רווח גולמי', cls: 'sw', style: 'background: #3B4BD8' }, { key: 'cost', label: 'עלות חומרי גלם', cls: 'sw', style: 'background: #B7BCD0' }, { key: 'h', label: 'גובה העמודה = הכנסה', cls: 'swn', style: '' }];
    return {
      ticks, bars, hasTip: !!tip, tip: tip || {}, isLine, isBar: !isLine, lines, legend, baseX1: L, baseX2: R,
      views: [['bar', 'עמודות'], ['line', 'קו']].map(([v, label]) => ({ key: v, label, cls: (view || 'bar') === v ? 'on' : '', pressed: (view || 'bar') === v, pick: () => this.setTrendView(type.replace('mail-', ''), v) }))
    };
  }

  kStats(k) {
    const thr = this.state.settings.expDays;
    let low = 0, exp = 0, expired = 0;
    this.ITEMS.forEach((it) => {
      const q = this.state.qty[k][it.id];
      if (q < it.min) low++;
      const d = this.daysLeft(it, k);
      if (q > 0 && d <= thr) exp++;
      if (q > 0 && d < 0) expired++;
    });
    return Object.assign({ low, exp, expired }, this.prodTotals(k));
  }

  flash(msg) {
    this.setState({ toast: msg });
    clearTimeout(this._t);
    this._t = setTimeout(() => this.setState({ toast: '' }), 2800);
  }

  /* העוזר האישי: התראות חשובות. הגמד מדלג למרכז המסך ומקריא אותן */
  gnomeAlerts() {
    const s = this.state, out = [];
    const openKitchen = (kid, tab) => this.setState({ screen: 'kitchen', kitchenId: kid, tab, recId: null, navOpen: false });
    this.KITCHENS.forEach((kk) => {
      this.ITEMS.forEach((it) => {
        const q = s.qty[kk.id][it.id];
        if (q !== 0) return;
        const hasSent = s.orders.some((o) => o.k === kk.id && o.status === 'sent' && o.lines.some((l) => l.id === it.id));
        const hasDraft = s.orders.some((o) => o.k === kk.id && o.sup === it.sup && o.status === 'draft');
        const dishes = this.dayDishes(this.TODAY).filter((x) => x.planned > 0 && (this.recOf(x.name) || []).some((l) => l.id === it.id))
          .map((x) => x.name).filter((n, i, a) => a.indexOf(n) === i);
        out.push({
          key: 'out:' + kk.id + ':' + it.id, tag: 'אזל מהמלאי', cls: 'pill p-bad',
          text: 'שמתי לב שאין יותר ' + it.name + ' במלאי של ' + kk.name + '.' +
            (dishes.length ? ' בתפריט של היום זה נכנס ל' + dishes.join(', ל') + '.' : '') +
            (hasSent ? ' כבר הזמנו, והסחורה בדרך.' : hasDraft ? ' יש הזמנה מוכנה שמחכה לאישור שלך.' : ' כדאי להזמין מ' + it.sup + ' עוד היום.'),
          btn: hasSent ? 'למלאי המטבח' : hasDraft ? 'לאישור ההזמנה' : 'הכן מייל לספק',
          go: hasSent ? () => openKitchen(kk.id, 'inv') : () => this.orderForItem(kk.id, it.id)
        });
      });
    });
    this.KITCHENS.forEach((kk) => {
      this.ITEMS.forEach((it) => {
        const q = s.qty[kk.id][it.id];
        if (q > 0 && this.daysLeft(it, kk.id) < 0) {
          out.push({
            key: 'exp:' + kk.id + ':' + it.id, tag: 'פג תוקף', cls: 'pill p-bad',
            text: 'עבר התוקף של ' + it.name + ' (' + q + ' ' + it.unit + ') ב' + kk.name + '. צריך להוציא מהמטבח ולסמן כפחת.',
            btn: 'לניהול התוקף', go: () => openKitchen(kk.id, 'exp')
          });
        }
      });
    });
    // ירידה ברווח והפסד: אדום קודם
    this.plAlerts().forEach((a) => {
      out.push({
        key: a.key, tag: a.tag, cls: a.cls,
        text: a.text + (a.level === 'red' ? ' זו ירידה חדה, כדאי לבדוק את זה עוד היום.' : ' כדאי לבדוק מה השתנה.'),
        btn: 'לדוח ההשוואה', go: () => this.setState({ screen: 'reports', aud: a.aud, kitchenId: s.kitchenId, navOpen: false })
      });
    });
    this.dayAlerts().forEach((a) => out.push(a));
    s.anns.forEach((a) => {
      if (!a.urgent) return;
      a.to.forEach((kid) => {
        if (a.reads[kid]) return;
        out.push({
          key: 'ann:' + a.id + ':' + kid, tag: 'הודעה דחופה', cls: 'pill p-pur',
          text: a.title + '. כדאי לקרוא את ההנחיות ולטפל בזה עכשיו.',
          btn: 'לקריאת ההודעה', go: () => openKitchen(kid, 'tasks')
        });
      });
    });
    return out;
  }

  // רווח והפסד ליום עבודה אחד (אינדקס ב-HISTDAYS), כל המטבחים ושני התפריטים. פחת חומרי הגלם נרשם לכל יום, כמו בדוח השבועי
  dayPL(d) {
    let rev = 0, cost = 0;
    this.KITCHENS.forEach((kk) => {
      this.dayProd(kk.id, d, 'all').forEach((r) => { rev += r.rev; cost += (r.out + r.left + r.thrown) * r.unit; });
    });
    return { rev, cost, profit: rev - cost };
  }

  // היום מול ממוצע ימי העבודה הקודמים
  dayNow() {
    const n = this.HISTDAYS.length, cur = this.dayPL(n - 1);
    const avg = this.HISTDAYS.slice(0, n - 1).reduce((a, x, i) => a + this.dayPL(i).profit, 0) / Math.max(1, n - 1);
    return Object.assign({ label: this.HISTDAYS[n - 1].label, avg }, cur);
  }

  // התראות רווח והפסד יומיות. רווח של 100% על העלות הוא יום רגיל בנתוני הדוגמה, ולכן הוא רק בסימולציה
  dayAlerts() {
    const v = this.dayNow(), out = [];
    if (v.rev > 0 && v.cost > v.rev * (1 + this.DROP_RED)) out.push(this.dayStory('loss', v));
    if (v.avg > 0 && v.profit < v.avg * (1 - this.DROP_RED)) out.push(this.dayStory('drop', v));
    if (v.avg > 0 && v.profit >= v.avg * 2) out.push(this.dayStory('double', v));
    return out;
  }

  // מה העוזר אומר על יום. sad: צער עמוק, מה קרה ואיך מתייעלים. happy: שמחה, הוא מוריד משקפיים וקורץ
  dayStory(kind, v) {
    const m = (n) => this.money(n), day = 'היום (' + v.label + ')';
    const base = { key: 'day:' + kind, where: 'דוחות · יומי · הכול', btn: 'לדוח היומי', go: () => this.setState({ screen: 'reports', aud: 'all', period: 'day', navOpen: false }) };
    if (kind === 'loss') {
      const over = this.pct(v.cost / v.rev - 1);
      return Object.assign(base, { mood: 'sad', tag: 'קריטי · הפסד יומי', cls: 'pill p-bad',
        short: v.label + ': עלות חומרי הגלם גבוהה ב-' + over + ' מההכנסה. הפסד של ' + m(v.cost - v.rev) + '.',
        text: 'לאאאאא! מה קרה פה?! ' + day + ' נגמר בהפסד של ' + m(v.cost - v.rev) + '. עלות חומרי הגלם (' + m(v.cost) + ') גבוהה ב-' + over + ' מההכנסה (' + m(v.rev) + ').\n' +
          'מה קרה: בישלנו לפי תכנון מלא, אבל הגיעו פחות סועדים. מנות שלא נמכרו נזרקו, ואיתן גם חומרי גלם עם תוקף קצר: שמנת מתוקה, עגבניות ולחמניות.\n' +
          'איך מתייעלים: מזמינים שמנת ועגבניות פעמיים בשבוע בכמויות קטנות, במקום הזמנה אחת גדולה. מה שפג מחר הופך היום למנת שף: עגבניות לשקשוקה, לחמניות לקרוטונים או לפודינג לחם. ושעה לפני הסגירה מציעים לעובדי מטה ארוחה הביתה בחצי מחיר, במקום לזרוק.' });
    }
    if (kind === 'drop') {
      const tom = this.item('tom'), drop = this.pct(1 - v.profit / v.avg);
      return Object.assign(base, { mood: 'sad', tag: 'קריטי · צניחה ברווח', cls: 'pill p-bad',
        short: v.label + ': הרווח צנח ב-' + drop + ' לעומת ממוצע הימים הקודמים (' + m(v.profit) + ' במקום ' + m(v.avg) + ').',
        text: 'לאאאא, מה קרה פה? הרווח של ' + day + ' צנח ל-' + m(v.profit) + ', ירידה של ' + drop + ' לעומת ממוצע הימים הקודמים (' + m(v.avg) + ').\n' +
          'למה: ה' + tom.name + ' התייקרו אצל ' + tom.sup + ' מ-' + this.money2(tom.prev) + ' ל-' + this.money2(tom.price) + ' לק"ג, ובאותו יום נשארו בסוף הקו הרבה מנות עיקריות שהכנו מראש.\n' +
          'איך מתייעלים: אצל ' + tom.alt + ' ה' + tom.name + ' עולות ' + this.money2(tom.altPrice) + ', כדאי לעבור. מקטינים בתכנון של השבוע הבא את המנה שנשארה, מבשלים בשני סבבים לפי התור בקו, ומציבים את המנה הרווחית ביותר ראשונה בקו.' });
    }
    if (kind === 'double') {
      return Object.assign(base, { mood: 'happy', tag: 'יום שיא · הרווח הוכפל', cls: 'pill p-ok',
        short: v.label + ': הרווח הוכפל, ' + m(v.profit) + ' לעומת ממוצע של ' + m(v.avg) + '.',
        text: 'יששש! איזה יום! הרווח של ' + day + ' הוכפל: ' + m(v.profit) + ' לעומת ממוצע של ' + m(v.avg) + ' בימים הקודמים, פי ' + (v.profit / v.avg).toLocaleString('he-IL', { maximumFractionDigits: 1 }) + '.\n' +
          'מה עבד: הגיעו יותר סועדים, כמעט לא נשארו מנות, והפחת ירד. ככה עושים את זה! כדאי לשמור את התכנון של היום ולחזור עליו.' });
    }
    return Object.assign(base, { mood: 'happy', tag: 'רווח של 100%', cls: 'pill p-ok',
      short: v.label + ': רווח של ' + this.pct(v.profit / v.cost) + ' על עלות חומרי הגלם.',
      text: 'וואו, תראו את זה! ' + day + ' הרווח הגיע ל-' + m(v.profit) + ', יותר מכל עלות חומרי הגלם (' + m(v.cost) + '). רווח של ' + this.pct(v.profit / v.cost) + ' על העלות: כל שקל שהשקענו בחומרי גלם חזר אלינו יותר מכפול. אלופים!' });
  }

  // התראה מדומה למסך ההתראות. משתמשת בנתוני היום, ולא משנה שום דבר במערכת
  simAlert(id) {
    const v = this.dayNow(), kk = this.KITCHENS[0];
    const openKitchen = (tab) => this.setState({ screen: 'kitchen', kitchenId: kk.id, tab, recId: null, navOpen: false });
    if (id === 'loss') { const cost = v.rev * 1.34; return this.dayStory('loss', Object.assign({}, v, { cost, profit: v.rev - cost })); }
    if (id === 'drop') { const profit = v.avg * 0.62; return this.dayStory('drop', Object.assign({}, v, { cost: v.rev - profit, profit })); }
    if (id === 'double') { const rev = v.rev * 1.4, profit = v.avg * 2.1; return this.dayStory('double', Object.assign({}, v, { rev, cost: rev - profit, profit })); }
    if (id === 'markup') { const cost = v.rev / 2.12; return this.dayStory('markup', Object.assign({}, v, { cost, profit: v.rev - cost })); }
    const chk = this.item('chk'), crm = this.item('crm');
    const ann = this.state.anns.find((a) => a.urgent) || this.state.anns[0];
    const sims = {
      out: { tag: 'אזל מהמלאי', cls: 'pill p-bad', text: 'שמתי לב שאין יותר ' + chk.name + ' במלאי של ' + kk.name + '. הוא נכנס לשניצל, לשווארמה ולנתחי עוף. כדאי להזמין מ' + chk.sup + ' עוד היום.', btn: 'למלאי המטבח', go: () => openKitchen('inv') },
      exp: { tag: 'פג תוקף', cls: 'pill p-bad', text: 'עבר התוקף של ' + crm.name + ' (4 ' + crm.unit + ') ב' + kk.name + '. צריך להוציא מהמטבח ולסמן כפחת.', btn: 'לניהול התוקף', go: () => openKitchen('exp') },
      pl: { tag: 'ירידה ברווח', cls: 'pill p-low', text: 'הרווח הגולמי של כל המטבח ירד ב-14.0% השבוע לעומת ממוצע 4 השבועות הקודמים. כדאי לבדוק מה השתנה.', btn: 'לדוח ההשוואה', go: () => this.setState({ screen: 'reports', aud: 'all', navOpen: false }) },
      ann: { tag: 'הודעה דחופה', cls: 'pill p-pur', text: (ann ? ann.title : 'הודעה מההנהלה') + '. כדאי לקרוא את ההנחיות ולטפל בזה עכשיו.', btn: 'לקריאת ההודעה', go: () => openKitchen('tasks') }
    };
    return Object.assign({ key: 'sim:' + id }, sims[id]);
  }

  // הטריגרים של הסימולציה: בכרטיס שבמסך ההתראות ובמעגל סביב העוזר
  simItems() {
    return [
      { id: 'out', label: 'אזל מהמלאי', c: 'r', group: 'day' }, { id: 'exp', label: 'פג תוקף', c: 'r', group: 'day' },
      { id: 'pl', label: 'ירידה ברווח השבועי', c: 'o', group: 'day' }, { id: 'ann', label: 'הודעה דחופה', c: 'p', group: 'day' },
      { id: 'loss', label: 'הפסד של מעל 25%', c: 'r', group: 'bad' }, { id: 'drop', label: 'צניחה של מעל 25% ברווח', c: 'r', group: 'bad' },
      { id: 'double', label: 'הרווח הוכפל', c: 'g', group: 'good' }, { id: 'markup', label: 'רווח של 100% על העלות', c: 'g', group: 'good' }
    ];
  }

  // המעגל: מתחיל מימין למעלה, יורד מתחת לעוזר ועולה משמאל. החלק העליון נשאר פנוי לבועה
  simRing() {
    const cur = this.state.gnomeSim && this.state.gnomeSim.simId;
    return this.simItems().map((x, i) => {
      const a = (15 - i * 30) * Math.PI / 180, on = cur === x.id;
      return {
        key: x.id, label: x.label, dot: 'gdot ' + x.c, cls: 'gchip' + (on ? ' on' : ''), pressed: on,
        style: 'left: calc(var(--rx) * ' + Math.cos(a).toFixed(3) + '); top: calc(var(--ry) * ' + (-Math.sin(a)).toFixed(3) + '); animation-delay: calc(var(--gd) + ' + (0.15 + i * 0.05).toFixed(2) + 's)',
        fire: () => this.gnomeSimulate(x.id)
      };
    });
  }

  // פותח את העוזר במצב סימולציה, או מחליף את ההתראה בלי לסגור אותו
  gnomeSimulate(id) {
    const a = Object.assign(id === 'idle'
      ? { key: 'sim:idle', tag: '', text: 'בוחרים התראה מהמעגל, ואני מציג ומקריא אותה כאילו היא קרתה עכשיו. אפשר לעבור בין ההתראות בלי לסגור אותי.' }
      : this.simAlert(id), { simId: id });
    clearTimeout(this._gt);
    this.setState((st) => {
      const opening = !st.gnomeOpen || st.gnomeOut;
      // מאיזה מצב רוח הגענו. באותו מצב רוח נשאר הערך הקודם, כדי שהמשקפיים לא יחזרו על פנים בלי משקפיים
      const was = opening ? '' : ((st.gnomeSim && st.gnomeSim.mood) || '');
      return { gnomeFrom: opening ? '' : was === (a.mood || '') ? st.gnomeFrom : was, gnomeSim: a, gnomeSimMode: true, gnomeOpen: true, gnomeOut: false, gnomeIdle: false, gnomeN: st.gnomeN + 1, gnomeOpenN: opening ? st.gnomeN + 1 : st.gnomeOpenN };
    });
  }

  gnomeAutoSaved() {
    try { return window.localStorage.getItem('gnomeAuto') === '1'; } catch (e) { return false; }
  }

  // בהפעלה, ההתראות שכבר קיימות נחשבות כאילו נראו. העוזר יקפוץ רק על התראה חדשה
  gnomeToggleAuto() {
    const on = !this.state.gnomeAuto;
    try { window.localStorage.setItem('gnomeAuto', on ? '1' : '0'); } catch (e) { /* אין אחסון: ההגדרה תחזיק עד רענון */ }
    const gnomeSeen = {};
    if (on) this.gnomeAlerts().forEach((a) => { gnomeSeen[a.key] = true; });
    this.setState(on ? { gnomeAuto: true, gnomeSeen } : { gnomeAuto: false });
  }

  // קונפטי ליום טוב
  gnomeConfetti() {
    if (this._confetti) return this._confetti;
    const colors = ['#3B4BD8', '#037F4C', '#FDAB3D', '#C62F4A', '#5B3FD1', '#2BB5E0'];
    return (this._confetti = Array.from({ length: 22 }, (_, i) => ({
      key: i, style: 'left: ' + ((i * 41 + 7) % 100) + '%; background: ' + colors[i % colors.length] + '; animation-delay: calc(var(--gd) + ' + (0.45 + (i * 0.13) % 1.1).toFixed(2) + 's); animation-duration: ' + (2.4 + (i % 5) * 0.3).toFixed(1) + 's'
    })));
  }

  gnomeList() {
    const s = this.state;
    if (s.gnomeSim) return [s.gnomeSim];
    if (s.gnomeIdle) return [{ key: 'idle', tag: '', text: 'הכול בסדר במטבח! אין כרגע התראות חשובות. אם משהו ייגמר במלאי, אקפוץ להגיד לך.', btn: '' }];
    const all = this.gnomeAlerts();
    return s.gnomeQ.map((key) => all.find((a) => a.key === key)).filter(Boolean);
  }

  gnomeCheck() {
    const s = this.state;
    // בזמן סימולציה העוזר מציג רק את ההתראה שהופעלה
    if (s.screen === 'login' || s.gnomeSim) return;
    // העוזר קופץ מעצמו רק אם הפעילו את זה בהגדרות ההתראות, ורק במטבח ובהתראות. אחרת התראה חדשה מחכה, והאווטאר בפינה מסמן אותה
    const autoOpen = s.gnomeAuto && (s.screen === 'kitchen' || s.screen === 'alerts');
    const keys = this.gnomeAlerts().map((a) => a.key);
    const fresh = autoOpen ? keys.filter((key) => !s.gnomeSeen[key]) : [];
    const stale = Object.keys(s.gnomeSeen).filter((key) => keys.indexOf(key) < 0);
    const emptied = s.gnomeOpen && !s.gnomeIdle && !s.gnomeQ.some((key) => keys.indexOf(key) >= 0);
    if (!fresh.length && !stale.length && !emptied) return;
    // התראה חדשה קופצת ראשונה. התראה שנפתרה נשכחת, כדי שהגמד יקפוץ שוב אם היא תחזור
    const gnomeSeen = {};
    keys.forEach((key) => { if (s.gnomeSeen[key] || fresh.indexOf(key) >= 0) gnomeSeen[key] = true; });
    if (fresh.length) clearTimeout(this._gt);
    this.setState((st) => {
      const gnomeQ = fresh.concat(st.gnomeIdle ? [] : st.gnomeQ.filter((key) => keys.indexOf(key) >= 0));
      if (!fresh.length) return { gnomeSeen, gnomeQ, gnomeOpen: st.gnomeOpen && (st.gnomeIdle || gnomeQ.length > 0) };
      const opening = !st.gnomeOpen || st.gnomeOut;
      return { gnomeSeen, gnomeQ, gnomeOpen: true, gnomeOut: false, gnomeIdle: false, gnomeN: st.gnomeN + 1, gnomeOpenN: opening ? st.gnomeN + 1 : st.gnomeOpenN };
    });
  }

  gnomeSummon() {
    const keys = this.gnomeAlerts().map((a) => a.key);
    const gnomeSeen = {};
    keys.forEach((key) => { gnomeSeen[key] = true; });
    clearTimeout(this._gt);
    this.setState((st) => ({ gnomeSim: null, gnomeSimMode: false, gnomeSeen, gnomeQ: keys, gnomeIdle: !keys.length, gnomeOpen: true, gnomeOut: false, gnomeN: st.gnomeN + 1, gnomeOpenN: st.gnomeN + 1 }));
  }

  gnomeClose() {
    if (!this.state.gnomeOpen || this.state.gnomeOut) return;
    this.setState({ gnomeOut: true });
    clearTimeout(this._gt);
    this._gt = setTimeout(() => this.setState({ gnomeOpen: false, gnomeOut: false, gnomeQ: [], gnomeIdle: false, gnomeSim: null, gnomeSimMode: false, gnomeFrom: '' }), 1100);
  }

  gnomeNext() {
    if (this.gnomeList().length > 1) this.setState((st) => ({ gnomeQ: st.gnomeQ.slice(1), gnomeN: st.gnomeN + 1 }));
    else this.gnomeClose();
  }

  // עמודות או קו, לכל דוח. נשמר בדפדפן של המשתמש בלבד
  trendViewSaved() {
    const def = { week: 'bar', month: 'bar' };
    try { const v = JSON.parse(window.localStorage.getItem('trendView') || 'null'); return v && v.week && v.month ? v : def; } catch (e) { return def; }
  }

  setTrendView(type, view) {
    const v = Object.assign({}, this.state.trendView, { [type]: view });
    try { window.localStorage.setItem('trendView', JSON.stringify(v)); } catch (e) { /* אין אחסון: הבחירה תחזיק עד רענון */ }
    this.setState({ trendView: v });
  }

  gnomeMuteSaved() {
    try { return window.localStorage.getItem('gnomeMute') === '1'; } catch (e) { return false; }
  }

  gnomeToggleMute() {
    const m = !this.state.gnomeMute;
    try { window.localStorage.setItem('gnomeMute', m ? '1' : '0'); } catch (e) { /* אין אחסון: ההגדרה תחזיק עד רענון */ }
    this.setState({ gnomeMute: m });
    this._gSaid = null; // הקראה מחדש של ההתראה הנוכחית, עם קול או בלעדיו
  }

  gnomeVoice() {
    const synth = window.speechSynthesis;
    if (!synth) return null;
    const all = synth.getVoices();
    if (!all.length) return 'default';
    const he = all.filter((v) => /^(he|iw)\b/i.test(v.lang));
    // קול גברי: Avri (הקול הטבעי של Edge), אחריו Asaf (של Windows). קולות נשיים מוכרים (Hila, Carmit) רק אם אין אחר
    const rank = (v) => /avri/i.test(v.name) ? 0 : /asaf/i.test(v.name) ? 1 : /hila|carmit/i.test(v.name) ? 9 : /natural|online/i.test(v.name) ? 2 : 3;
    return he.slice().sort((a, b) => rank(a) - rank(b))[0] || null;
  }

  // טקסט להקראה: סכומים בשקלים ויחידות במילים, כדי שהקול לא יקרא סימנים
  gnomeSpoken(text) {
    return text.replace(/-?₪(\d[\d,]*(?:\.\d+)?)/g, (m, n) => n + ' שקלים').replace(/(\d+)\.0%/g, '$1%').replace(/ק"ג/g, 'קילו').replace(/\n/g, ' ');
  }

  gnomeTtsUrl(text, mood) {
    return '/api/tts?m=' + (mood || '') + '&t=' + encodeURIComponent(this.gnomeSpoken(text));
  }

  // הגמד מדבר בקול של ElevenLabs. אם השרת לא עונה או שהדפדפן חוסם, הקול העברי של הדפדפן. הפה זז כל עוד הוא מדבר
  gnomeSay(text, mood) {
    this.gnomeHush();
    const quiet = () => { this.setState({ gnomeTalk: true }); this._gtt = setTimeout(() => this.setState({ gnomeTalk: false }), Math.min(9000, 800 + text.length * 55)); };
    if (this.state.gnomeMute || !window.Audio) { quiet(); return; }
    const a = new Audio(this.gnomeTtsUrl(text, mood));
    let started = false;
    const fallback = () => { if (this._ga !== a) return; this._ga = null; clearTimeout(this._gat); a.pause(); this.gnomeSayBrowser(text, mood); };
    a.onplaying = () => { if (this._ga === a) { started = true; clearTimeout(this._gat); this.setState({ gnomeTalk: true }); } };
    a.onended = () => { if (this._ga === a) { this._ga = null; this.setState({ gnomeTalk: false }); } };
    a.onerror = () => { if (!started) fallback(); else if (this._ga === a) { this._ga = null; this.setState({ gnomeTalk: false }); } };
    this._ga = a;
    // טקסט חדש נוצר בפעם הראשונה תוך שנייה או שתיים. אם לא התחיל אחרי 12 שניות, עוברים לקול של הדפדפן
    this._gat = setTimeout(() => { if (!started) fallback(); }, 12000);
    const p = a.play();
    if (p && p.catch) p.catch(() => { if (!started) fallback(); });
  }

  gnomeSayBrowser(text, mood) {
    const synth = window.speechSynthesis;
    text = this.gnomeSpoken(text);
    const voice = !this.state.gnomeMute && synth && window.SpeechSynthesisUtterance ? this.gnomeVoice() : null;
    this.setState({ gnomeTalk: true });
    const quiet = () => { this._gtt = setTimeout(() => this.setState({ gnomeTalk: false }), Math.min(9000, 800 + text.length * 55)); };
    if (!voice) { quiet(); return; }
    const u = new SpeechSynthesisUtterance(text);
    if (voice === 'default') u.lang = 'he-IL'; else { u.voice = voice; u.lang = voice.lang; }
    // עצוב: איטי ונמוך. שמח: מהיר וגבוה
    u.rate = mood === 'sad' ? 0.9 : mood === 'happy' ? 1.06 : 1;
    u.pitch = mood === 'sad' ? 0.78 : mood === 'happy' ? 1.15 : 0.95;
    u.onend = () => { if (this._gu === u) { this._gu = null; this.setState({ gnomeTalk: false }); } };
    // הדפדפן חסם את הקול: הפה ממשיך לזוז בשקט
    u.onerror = () => { if (this._gu === u) { this._gu = null; quiet(); } };
    this._gu = u;
    synth.speak(u);
  }

  gnomeHush() {
    clearTimeout(this._gtt); clearTimeout(this._gat);
    // ההורדה ממשיכה ברקע, כדי שהקול יישמר ב-CDN לפעם הבאה
    if (this._ga) { const a = this._ga; this._ga = null; a.pause(); }
    if (this._gu) { this._gu = null; if (window.speechSynthesis) window.speechSynthesis.cancel(); }
    if (this.state.gnomeTalk) this.setState({ gnomeTalk: false });
  }

  gnomeVoiceSync() {
    const s = this.state;
    const cur = s.gnomeOpen && !s.gnomeOut && s.screen !== 'login' ? this.gnomeList()[0] : null;
    const id = cur ? cur.key + '#' + s.gnomeN + (s.gnomeMute ? 'm' : '') : null;
    if (id === this._gSaid) return;
    this._gSaid = id;
    clearTimeout(this._gst);
    this.gnomeHush();
    if (!cur) return;
    const text = (cur.tag ? cur.tag + '. ' : '') + cur.text;
    // בכניסה מחכים שהגמד יסיים לדלג למרכז
    this._gst = setTimeout(() => this.gnomeSay(text, cur.mood), s.gnomeN === s.gnomeOpenN ? 1650 : 350);
  }

  catSup(cat) {
    const it = this.ITEMS.find((x) => x.cat === cat);
    return it ? it.sup : 'ספק כללי';
  }

  addItems(cat, list) {
    const k = this.state.kitchenId;
    const d = this.CAT_DEF[cat] || ['יח׳', 30];
    const qty = JSON.parse(JSON.stringify(this.state.qty));
    let added = 0, merged = 0;
    list.forEach((l, i) => {
      const name = (l.name || '').trim();
      if (!name) return;
      const n = Math.max(0, parseFloat(l.qty) || 0);
      const same = this.ITEMS.find((it) => it.name === name);
      if (same) { qty[k][same.id] = Math.round((qty[k][same.id] + n) * 10) / 10; merged++; return; }
      const id = 'n' + Date.now() + '_' + i;
      this.ITEMS.push({ id, name, cat, unit: l.unit || d[0], min: 0, price: 0, prev: 0, sup: this.catSup(cat), alt: '—', altPrice: 0, exp: d[1] });
      this.KITCHENS.forEach((kk) => { qty[kk.id][id] = kk.id === k ? n : 0; });
      added++;
    });
    this.setState({ qty });
    return { added, merged };
  }

  unitOf(u, cat) {
    const d = (this.CAT_DEF[cat] || ['יח׳'])[0];
    if (!u) return d;
    if (/^(ק["״']?ג|קילו|kg)/i.test(u)) return 'ק"ג';
    if (/^(ליטר|ל["׳']?|l)$/i.test(u)) return 'ליטר';
    if (/^(יח|יחידה|יחידות)/.test(u)) return 'יח׳';
    return d;
  }

  parseBulk(text, cat) {
    return text.split('\n').map((line) => line.trim()).filter(Boolean).map((line) => {
      const parts = line.split(/[,\t]/).map((x) => x.trim());
      let name = parts[0], rest = parts.slice(1).join(' ');
      if (parts.length === 1) {
        const m = line.match(/^(.*?)\s+(\d+(?:\.\d+)?)\s*(\S+)?$/);
        if (m) { name = m[1]; rest = m[2] + ' ' + (m[3] || ''); } else rest = '';
      }
      const q = rest.match(/(\d+(?:\.\d+)?)\s*(\S+)?/);
      return { name: name.trim(), qty: q ? q[1] : '', unit: this.unitOf(q && q[2], cat) };
    }).filter((l) => l.name);
  }

  parseMenu(text) {
    return text.split('\n').map((x) => x.trim()).filter(Boolean).map((line) => {
      let slot, rest;
      if (line.indexOf('\t') >= 0) { const p = line.split('\t').map((x) => x.trim()); slot = p[0]; rest = p.slice(1); }
      else {
        const i = line.indexOf(':');
        if (i < 0) return null;
        slot = line.slice(0, i).trim();
        rest = line.slice(i + 1).split(/[,،]/).map((x) => x.trim());
      }
      if (!slot || /^סוג מנה/.test(slot)) return null;
      return { slot, cells: [0, 1, 2, 3, 4].map((i) => rest[i] || '') };
    }).filter(Boolean);
  }

  setQty(k, id, delta) {
    this.setState((s) => {
      const qty = JSON.parse(JSON.stringify(s.qty));
      qty[k][id] = Math.max(0, qty[k][id] + delta);
      return { qty };
    });
  }

  markWaste(k, id) {
    const it = this.item(id);
    const q = this.state.qty[k][id];
    this.setState((s) => {
      const qty = JSON.parse(JSON.stringify(s.qty));
      qty[k][id] = 0;
      const rawWaste = JSON.parse(JSON.stringify(s.rawWaste));
      rawWaste[k].push({ id, amt: q, reason: 'פג תוקף' });
      return { qty, rawWaste };
    });
    this.flash(q + ' ' + it.unit + ' ' + it.name + ' סומנו כפחת, נגרעו מהמלאי ונוספו לדוח הפחת');
  }

  addDrafts(k, lines, src) {
    const s = this.state;
    const bySup = {};
    lines.forEach((l) => {
      const it = this.item(l.id);
      if (!bySup[it.sup]) bySup[it.sup] = [];
      bySup[it.sup].push({ id: l.id, qty: l.qty, recv: l.qty, inv: it.price });
    });
    const sups = Object.keys(bySup).filter((sup) => !s.orders.some((o) => o.k === k && o.sup === sup && o.status === 'draft'));
    if (!sups.length) return [];
    let n = s.nextOrd;
    const created = sups.map((sup) => ({ id: 'o' + n, num: 'ORD-' + (n++), k, sup, date: '22.10.2026', status: 'draft', src, lines: bySup[sup] }));
    this.setState({ orders: s.orders.concat(created), nextOrd: n });
    return created;
  }

  emailBody(o) {
    const kit = this.kitchen(o.k);
    const lines = o.lines.map((l) => { const it = this.item(l.id); return '• ' + it.name + ' – ' + l.qty + ' ' + it.unit; }).join('\n');
    return 'שלום ' + o.sup + ',\n\nנבקש להזמין עבור ' + kit.name + ' (' + kit.city + ') את הפריטים הבאים:\n' + lines +
      '\n\nאספקה מבוקשת: יום ראשון 25.10.2026, עד 08:00.\nנודה לאישור קבלת ההזמנה במייל חוזר.\n\nבתודה,\n' + kit.manager + '\n' + kit.name;
  }

  // ספקים נוספים שהמשתמש הוסיף (נשמרים בדפדפן). בפעם הראשונה נטענים ספקי דוגמה
  extraSupsSeed() {
    const meat = ['חזה עוף', 'בשר בקר טחון', 'שוקי עוף', 'בשר בקר לצלי', 'פרגיות'];
    const dairy = ['חלב 3%', 'שמנת מתוקה', 'גבינה צהובה'];
    const mk = (name, email, cat, factor, pick) => {
      const prices = {};
      this.ITEMS.filter((it) => it.cat === cat && (!pick || pick.indexOf(it.name) >= 0))
        .forEach((it) => { prices[it.id] = Math.round(it.price * factor * 10) / 10; });
      return { name, email, cat, prices };
    };
    return [
      mk('קצביית הגליל', 'orders@galil-butcher.example', 'קפואים', 0.93, meat),
      mk('בקר ועוף ישיר', 'sales@meat-direct.example', 'קפואים', 0.97, meat),
      mk('מחלבת הגולן', 'orders@golan-dairy.example', 'חלב', 0.95, dairy),
      mk('ירקות הכפר', 'orders@village-veg.example', 'ירקות ופירות', 0.92),
      mk('מאפיית הבוקר', 'orders@morning-bakery.example', 'לחמים', 0.96)
    ];
  }

  extraSupsSaved() {
    try { const v = window.localStorage.getItem('extraSups'); if (v) return JSON.parse(v); } catch (e) { /* בלי אחסון */ }
    return this.extraSupsSeed();
  }

  saveExtraSups(list) {
    try { window.localStorage.setItem('extraSups', JSON.stringify(list)); } catch (e) { /* בלי אחסון */ }
    this.setState({ extraSups: list });
  }

  supEmail(name) {
    const ex = this.state.extraSups.find((e) => e.name === name);
    return ex && ex.email ? ex.email : '[אימייל הספק]';
  }

  // כל הספקים החלופיים לפריט, מהזול ליקר. מחיר null = יתבקש מחיר במייל
  altsFor(it) {
    const out = [];
    const add = (name, price) => {
      if (!name || name === it.sup) return;
      const cur = out.find((o) => o.name === name);
      if (cur) { if (cur.price == null) cur.price = price; return; }
      out.push({ name, price });
    };
    add(it.alt, it.altPrice);
    this.state.extraSups.forEach((e) => { if (e.prices[it.id] != null) add(e.name, e.prices[it.id]); });
    const rel = [it.sup, it.alt];
    this.ITEMS.filter((x) => x.cat === it.cat && (rel.indexOf(x.sup) >= 0 || rel.indexOf(x.alt) >= 0))
      .forEach((x) => { add(x.sup, null); add(x.alt, null); });
    out.forEach((o) => { if (o.price == null) o.price = this.swPrice(it, o.name); });
    return out.sort((a, b) => (a.price == null) - (b.price == null) || a.price - b.price);
  }

  openSupForm() {
    this.setState({ supOpen: true, supForm: { name: '', email: '', cat: 'קפואים', prices: {} } });
  }

  saveSupForm() {
    const f = this.state.supForm;
    const name = f.name.trim();
    if (!name) { this.flash('צריך למלא שם ספק'); return; }
    const taken = this.state.extraSups.some((e) => e.name === name) || this.ITEMS.some((x) => x.sup === name || x.alt === name);
    if (taken) { this.flash('כבר קיים ספק בשם הזה'); return; }
    const prices = {};
    Object.keys(f.prices).forEach((id) => { const p = parseFloat(f.prices[id]); if (p > 0) prices[id] = p; });
    if (!Object.keys(prices).length) { this.flash('צריך למלא מחיר לפחות לפריט אחד שהספק מוכר'); return; }
    this.saveExtraSups(this.state.extraSups.concat([{ name, email: f.email.trim(), cat: f.cat, prices }]));
    this.setState({ supOpen: false, supForm: null });
    this.flash('הספק ' + name + ' נוסף, ויופיע כחלופה בפריטים שמילאת להם מחיר');
  }

  // מעבר לספק חלופי: מייל הזמנה לספק החדש ומייל הפסקת התקשרות לספק היקר
  swPrice(it, sup) {
    const ex = this.state.extraSups.find((e) => e.name === sup);
    if (ex && ex.prices[it.id] != null) return ex.prices[it.id];
    if (sup === it.alt) return it.altPrice;
    const same = this.ITEMS.find((x) => x.name === it.name && x.sup === sup);
    return same ? same.price : null;
  }

  swNewMail(it, sup, qty) {
    const kit = this.KITCHENS[0];
    const p = this.swPrice(it, sup);
    const priceLine = p != null
      ? '• מחיר לפי המחירון שלכם: ' + this.money2(p) + ' ל' + it.unit + ' (כ-' + this.money(p * qty) + ' בחודש)'
      : '• מחיר: נבקש הצעת מחיר ל' + it.unit;
    return 'שלום ' + sup + ',\n\nאנחנו מעוניינים להתחיל לרכוש מכם ' + it.name + ' עבור ' + kit.name + ' (' + kit.city + ').\n\nפרטי ההזמנה:\n' +
      '• פריט: ' + it.name + '\n• כמות חודשית משוערת: ' + qty + ' ' + it.unit + '\n' + priceLine +
      '\n• תדירות אספקה: פעם בשבוע\n• תחילת אספקה: 01.11.2026\n• כתובת אספקה: ' + kit.name + ', ' + kit.city +
      '\n\nנודה לאישור המחיר ומועד האספקה הראשונה במייל חוזר.\n\nבתודה,\n' + kit.manager + '\n' + kit.name;
  }

  swCancelMail(it, scope) {
    const kit = this.KITCHENS[0];
    const sign = '\n\nתודה על שיתוף הפעולה עד היום,\n' + kit.manager + '\n' + kit.name;
    if (scope === 'all') {
      const its = this.ITEMS.filter((x) => x.sup === it.sup).map((x) => '• ' + x.name).join('\n');
      return 'שלום ' + it.sup + ',\n\nברצוננו להודיע על סיום ההתקשרות בין ' + kit.name + ' לבינכם, החל מ-01.11.2026 ובהתאם לתנאי ההסכם.\n' +
        'ההתקשרות כוללת את הפריטים:\n' + its + '\n\nהזמנות שכבר נשלחו יסופקו כרגיל. נבקש לשלוח חשבונית סופית ואישור על סגירת החשבון.' + sign;
    }
    return 'שלום ' + it.sup + ',\n\nברצוננו לעדכן שהחל מ-01.11.2026 נפסיק לרכוש מכם ' + it.name + '.\n' +
      'שאר ההזמנות ממשיכות כרגיל, והזמנות שכבר נשלחו יסופקו כמתוכנן.' + sign;
  }

  openSwitch(id) {
    const it = this.item(id);
    const qty = it.min * 4;
    const best = this.altsFor(it)[0];
    const alt = best ? best.name : it.alt;
    this.setState({ swId: id, swAlt: alt, swQty: qty, swScope: 'item', swNew: this.swNewMail(it, alt, qty), swCancel: this.swCancelMail(it, 'item') });
  }

  approveSwitch() {
    const s = this.state;
    const it = this.item(s.swId);
    const oldSup = it.sup;
    const move = (x, sup) => {
      const p = this.swPrice(x, sup);
      const old = { sup: x.sup, price: x.price };
      x.sup = sup; x.prev = x.price;
      if (p != null) x.price = p;
      x.alt = old.sup; x.altPrice = old.price;
    };
    const others = s.swScope === 'all' ? this.ITEMS.filter((x) => x.sup === oldSup && x !== it) : [];
    move(it, s.swAlt);
    others.forEach((x) => move(x, x.alt));
    this.setState({ swId: null, swapN: s.swapN + 1 });
    this.flash(s.swScope === 'all'
      ? 'נשלחו 2 מיילים. ' + it.name + ' עובר ל' + s.swAlt + ', וההתקשרות עם ' + oldSup + ' הסתיימה (שאר הפריטים עברו לספקים החלופיים שלהם).'
      : 'נשלחו 2 מיילים. ' + it.name + ' עובר ל' + s.swAlt + ', ו' + oldSup + ' עודכן שנפסיק לרכוש ממנו את הפריט.');
  }

  openEmail(o) { this.setState({ emailOrderId: o.id, emailBody: this.emailBody(o) }); }

  createOrders(k) {
    const lines = [];
    this.ITEMS.forEach((it) => {
      const q = this.state.qty[k][it.id];
      if (q < it.min) lines.push({ id: it.id, qty: it.min * 2 - q });
    });
    const created = this.addDrafts(k, lines, 'חוסרים');
    if (!created.length) { this.flash('אין חוסרים חדשים. הזמנות שכבר ממתינות לאישור נמצאות בלשונית ההזמנות.'); return; }
    this.setState({ tab: 'ord' });
    this.openEmail(created[0]);
    this.flash('נוצרו ' + created.length + ' הזמנות שממתינות לאישור, אחת לכל ספק');
  }

  orderForItem(k, id) {
    const it = this.item(id);
    const existing = this.state.orders.find((o) => o.k === k && o.sup === it.sup && o.status === 'draft');
    if (existing) { this.openEmail(existing); return; }
    const lines = this.ITEMS.filter((x) => x.sup === it.sup && this.state.qty[k][x.id] < x.min)
      .map((x) => ({ id: x.id, qty: x.min * 2 - this.state.qty[k][x.id] }));
    const created = this.addDrafts(k, lines, 'התראת חוסר');
    if (created.length) this.openEmail(created[0]);
  }

  confirmReceive(oid) {
    const s = this.state;
    const o = s.orders.find((x) => x.id === oid);
    const qty = JSON.parse(JSON.stringify(s.qty));
    let amount = 0, gap = false;
    o.lines.forEach((l) => {
      qty[o.k][l.id] += l.recv;
      amount += l.recv * l.inv;
      if (l.recv < l.qty || l.inv > this.item(l.id).price) gap = true;
    });
    const inv = { id: 'i' + s.nextInv, num: 'INV-' + s.nextInv, sup: o.sup, k: o.k, date: '22.10.2026', amount, match: gap ? 'gap' : 'ok', fwd: '' };
    this.setState({
      qty,
      orders: s.orders.map((x) => x.id === oid ? Object.assign({}, x, { status: 'received' }) : x),
      invoices: [inv].concat(s.invoices),
      nextInv: s.nextInv + 1,
      recId: null
    });
    this.flash('הסחורה נקלטה במלאי, והחשבונית נוספה לרשימת החשבוניות');
  }

  updateSurvey(id, fn) {
    this.setState((st) => ({ surveys: st.surveys.map((v) => v.id === id ? fn(JSON.parse(JSON.stringify(v))) : v) }));
  }

  intVal(v) { return Math.max(0, parseInt(v, 10) || 0); }

  // row: שורה מהדיווח של היום. השורה נשמרת במלואה, כדי ששינוי בשדה אחד לא יאפס את האחרים
  setProd(k, row, f, v) {
    const n = this.intVal(v);
    this.setState((s) => {
      const prod = JSON.parse(JSON.stringify(s.prod));
      prod[k] = prod[k] || {};
      const cur = prod[k][row.key] || { out: row.out, left: row.left, thrown: row.thrown };
      cur[f] = n;
      prod[k][row.key] = cur;
      return { prod };
    });
  }

  renderVals() {
    const s = this.state;
    const k = s.kitchenId;
    const kit = this.kitchen(k);
    const thr = s.settings.expDays;
    const go = (screen) => () => this.setState({ screen, navOpen: false, svId: null });
    const active = s.screen === 'kitchen' ? 'kitchens' : s.screen;
    const navCls = (key) => 'navbtn' + (active === key ? ' on' : '');
    const openKitchen = (kid, tab) => this.setState({ screen: 'kitchen', kitchenId: kid, tab, recId: null, navOpen: false });
    const titles = { kitchens: 'המטבח', menu: 'תפריט שבועי', recipes: 'מתכונים ועלות מנה', suppliers: 'ספקים ומחירונים', invoices: 'חשבוניות', reports: 'דוחות', alerts: 'התראות', announce: 'הודעות לצוות', surveys: 'סקרים', users: 'משתמשים והרשאות' };

    /* מטבחים */
    let nDishes = 0, nCost = 0, nLow = 0, nExp = 0;
    // המנה המובילה: מבין המנות העיקריות של היום (תוספות יוצאות לכל סועד ולכן תמיד יובילו)
    const topOf = (rows) => {
      const pool = rows.some((x) => x.main) ? rows.filter((x) => x.main) : rows;
      return pool.reduce((b, x) => (!b || x.out > b.out ? x : b), null);
    };
    const todayTop = topOf(this.periodAgg(this.KITCHENS.map((kk) => kk.id), 'day'));
    const kitchens = this.KITCHENS.map((kk) => {
      const st = this.kStats(kk.id);
      const kTop = topOf(this.periodAgg([kk.id], 'day'));
      nDishes += st.out; nCost += st.cost; nLow += st.low; nExp += st.exp;
      const fc = st.cost / st.rev;
      return {
        name: kk.name, city: kk.city, manager: kk.manager,
        top: kTop ? kTop.name + ' (' + kTop.out + ')' : '—',
        dishes: st.out.toLocaleString('he-IL'),
        cost: this.money(st.cost), rev: this.money(st.rev),
        wastePct: this.pct(st.waste / st.cost),
        fc: this.pct(fc), fcCls: this.fcCls(fc),
        low: st.low,
        lowCls: st.low ? 'pill p-low' : 'pill p-ok',
        lowText: st.low ? st.low + ' פריטים בחוסר' : 'מלאי תקין',
        expCls: st.exp ? 'pill p-bad' : 'pill p-ok',
        expText: st.exp ? st.exp + ' בתוקף קצר' : 'אין תוקף קצר',
        open: () => openKitchen(kk.id, 'tasks')
      };
    });

    /* ספירת מלאי */
    let cntDiffs = 0, cntVal = 0;
    const cntRows = this.ITEMS.map((it) => {
      const sys = s.qty[k][it.id];
      const raw = s.countVals[it.id];
      const val = raw === undefined ? sys : raw;
      const num = parseFloat(val);
      const diff = isNaN(num) ? 0 : Math.round((num - sys) * 10) / 10;
      if (diff !== 0) { cntDiffs++; cntVal += diff * it.price; }
      return {
        cat: it.cat, name: it.name, sys: sys + ' ' + it.unit, unit: it.unit, val, aria: 'נספר: ' + it.name,
        diff: diff === 0 ? 'תואם' : (diff > 0 ? '+' : '') + diff + ' ' + it.unit,
        diffCls: diff === 0 ? 'pill p-ok' : diff > 0 ? 'pill p-info' : 'pill p-bad',
        rowCls: diff === 0 ? '' : 'diff',
        set: (e) => { const v = e.target.value; this.setState((st) => ({ countVals: Object.assign({}, st.countVals, { [it.id]: v }) })); }
      };
    });
    const cnt = {
      on: s.countOn, off: !s.countOn, rows: cntRows,
      groups: this.CATS.map((c) => ({ key: c, name: c, rows: cntRows.filter((r) => r.cat === c) })).filter((g) => g.rows.length),
      summary: cntDiffs ? cntDiffs + ' פריטים עם פער · שווי הפער ' + (cntVal < 0 ? '-' : '+') + this.money(Math.abs(cntVal)) : 'הכול תואם למה שרשום במערכת',
      start: () => this.setState({ countOn: true, countVals: {}, niOpen: false }),
      cancel: () => this.setState({ countOn: false, countVals: {} }),
      confirm: () => {
        this.setState((st) => {
          const qty = JSON.parse(JSON.stringify(st.qty));
          Object.keys(st.countVals).forEach((id) => { const n = parseFloat(st.countVals[id]); if (!isNaN(n) && n >= 0) qty[k][id] = Math.round(n * 10) / 10; });
          return { qty, countOn: false, countVals: {} };
        });
        this.flash(cntDiffs ? 'הספירה נשמרה. ' + cntDiffs + ' פריטים עודכנו במלאי.' : 'הספירה נשמרה. לא נמצאו פערים.');
      }
    };

    /* פריט חדש */
    const supList = [];
    this.ITEMS.forEach((it) => { if (supList.indexOf(it.sup) < 0) supList.push(it.sup); });
    const catList = this.CATS.slice();
    const setNi = (f) => (e) => { const v = e.target.value; this.setState((st) => ({ ni: Object.assign({}, st.ni, { [f]: v }) })); };
    const ni = {
      open: s.niOpen,
      title: s.niEdit ? 'עריכת פריט' : 'פריט חדש במלאי', btn: s.niEdit ? 'שמור שינויים' : 'הוסף למלאי',
      name: s.ni.name, cat: s.ni.cat, sup: s.ni.sup, qty: s.ni.qty, min: s.ni.min, price: s.ni.price, exp: s.ni.exp,
      cats: catList.map((v) => ({ v })), sups: supList.map((v) => ({ v })),
      units: ['ק"ג', 'ליטר', 'יח׳'].map((v) => ({ v, cls: s.ni.unit === v ? 'on' : '', pick: () => this.setState((st) => ({ ni: Object.assign({}, st.ni, { unit: v }) })) })),
      setName: setNi('name'), setCat: setNi('cat'), setSup: setNi('sup'), setQty: setNi('qty'), setMin: setNi('min'), setPrice: setNi('price'), setExp: setNi('exp'),
      openForm: () => this.setState((st) => ({ niOpen: true, niEdit: null, bulkOpen: false, countOn: false, ni: st.niEdit ? { name: '', cat: st.ni.cat, unit: st.ni.unit, min: '', price: '', sup: st.ni.sup, exp: '', qty: '' } : st.ni })),
      close: () => this.setState({ niOpen: false, niEdit: null }),
      save: () => {
        const f = s.ni;
        if (!f.name.trim()) { this.flash('צריך שם לפריט'); return; }
        if (s.niEdit) {
          const it = this.item(s.niEdit);
          const price = parseFloat(f.price) || 0;
          Object.assign(it, { name: f.name.trim(), cat: f.cat, unit: f.unit, min: parseFloat(f.min) || 0, price, sup: f.sup, exp: parseInt(f.exp, 10) || it.exp });
          if (!it.prev) it.prev = price;
          if (it.alt === '—') it.altPrice = price;
          this.setState((st) => {
            const qty = JSON.parse(JSON.stringify(st.qty));
            qty[k][it.id] = Math.max(0, parseFloat(f.qty) || 0);
            return { qty, niOpen: false, niEdit: null, ni: { name: '', cat: f.cat, unit: f.unit, min: '', price: '', sup: f.sup, exp: '', qty: '' } };
          });
          this.flash('הפרטים של ' + it.name + ' עודכנו');
          return;
        }
        const id = 'n' + Date.now();
        const price = parseFloat(f.price) || 0;
        this.ITEMS.push({ id, name: f.name.trim(), cat: f.cat, unit: f.unit, min: parseFloat(f.min) || 0, price, prev: price, sup: f.sup, alt: '—', altPrice: price, exp: parseInt(f.exp, 10) || 30 });
        this.setState((st) => {
          const qty = JSON.parse(JSON.stringify(st.qty));
          this.KITCHENS.forEach((kk) => { qty[kk.id][id] = kk.id === k ? (parseFloat(f.qty) || 0) : 0; });
          return { qty, niOpen: false, ni: { name: '', cat: f.cat, unit: f.unit, min: '', price: '', sup: f.sup, exp: '', qty: '' } };
        });
        this.flash(f.name.trim() + ' נוסף למלאי של ' + kit.name);
      }
    };

    /* קבלה בלי הזמנה */
    const adhoc = {
      open: s.adhocOpen, btn: s.adhocOpen ? 'סגור קבלה בלי הזמנה' : '+ קבלה בלי הזמנה',
      toggle: () => this.setState({ adhocOpen: !s.adhocOpen }),
      sup: s.adhoc.sup, sups: supList.map((v) => ({ v })),
      items: this.ITEMS.map((it) => ({ id: it.id, name: it.name })),
      setSup: (e) => { const v = e.target.value; this.setState((st) => ({ adhoc: Object.assign({}, st.adhoc, { sup: v }) })); },
      lines: s.adhoc.lines.map((l, li) => ({
        id: l.id, qty: l.qty, unit: this.item(l.id).unit,
        setId: (e) => { const v = e.target.value; this.setState((st) => { const a = JSON.parse(JSON.stringify(st.adhoc)); a.lines[li].id = v; return { adhoc: a }; }); },
        setQty: (e) => { const v = e.target.value; this.setState((st) => { const a = JSON.parse(JSON.stringify(st.adhoc)); a.lines[li].qty = v; return { adhoc: a }; }); },
        remove: () => this.setState((st) => { const a = JSON.parse(JSON.stringify(st.adhoc)); a.lines.splice(li, 1); if (!a.lines.length) a.lines.push({ id: this.ITEMS[0].id, qty: '' }); return { adhoc: a }; })
      })),
      addLine: () => this.setState((st) => { const a = JSON.parse(JSON.stringify(st.adhoc)); a.lines.push({ id: this.ITEMS[0].id, qty: '' }); return { adhoc: a }; }),
      save: () => {
        const lines = s.adhoc.lines.map((l) => ({ id: l.id, n: parseFloat(l.qty) || 0 })).filter((l) => l.n > 0);
        if (!lines.length) { this.flash('צריך להזין לפחות כמות אחת'); return; }
        const num = 'ORD-' + s.nextOrd;
        const order = { id: 'o' + s.nextOrd, num, k, sup: s.adhoc.sup, date: '22.10.2026', status: 'received', src: 'קבלה בלי הזמנה', lines: lines.map((l) => ({ id: l.id, qty: l.n, recv: l.n, inv: this.item(l.id).price })) };
        const amount = lines.reduce((a, l) => a + l.n * this.item(l.id).price, 0);
        this.setState((st) => {
          const qty = JSON.parse(JSON.stringify(st.qty));
          lines.forEach((l) => { qty[k][l.id] = Math.round((qty[k][l.id] + l.n) * 10) / 10; });
          return {
            qty, orders: st.orders.concat([order]), nextOrd: st.nextOrd + 1,
            invoices: [{ id: 'i' + st.nextInv, num: 'INV-' + st.nextInv, sup: st.adhoc.sup, k, date: '22.10.2026', amount, match: 'ok', fwd: '' }].concat(st.invoices),
            nextInv: st.nextInv + 1, adhocOpen: false, adhoc: { sup: st.adhoc.sup, lines: [{ id: this.ITEMS[0].id, qty: '' }] }
          };
        });
        this.flash(lines.length + ' פריטים נקלטו למלאי מ' + s.adhoc.sup + '. נוספה חשבונית לבדיקה.');
      }
    };

    /* משימות היום */
    const sDone = s.shiftDone[k];
    const mkItem = (x) => ({
      t: x.t, sub: x.sub || '', auto: !!x.auto, done: !!sDone[x.id],
      cls: 'task' + (sDone[x.id] ? ' done' : ''),
      toggle: () => this.setState((st) => { const d = JSON.parse(JSON.stringify(st.shiftDone)); d[k][x.id] = !d[k][x.id]; return { shiftDone: d }; })
    });
    const openList = [
      { id: 'o1', t: 'בדיקת טמפרטורה במקררים ובמקפיאים', sub: 'מקרר 0–4 מעלות, מקפיא 18- ומטה' },
      { id: 'o2', t: 'עמדות העבודה נקיות ומוכנות' }
    ];
    s.orders.filter((o) => o.k === k && o.status === 'sent').forEach((o) => openList.push({ id: 'rcv-' + o.id, t: 'קבלת סחורה מ' + o.sup, sub: o.num + ' · ' + o.lines.length + ' פריטים · בלשונית קבלת סחורה', auto: true }));
    this.ITEMS.forEach((it) => {
      const q = s.qty[k][it.id];
      const d = this.daysLeft(it, k);
      if (q > 0 && d <= 1) openList.push({ id: 'exp-' + it.id, t: 'להשתמש היום או לסמן כפחת: ' + it.name, sub: q + ' ' + it.unit + ' · ' + (d < 0 ? 'פג תוקף' : d === 0 ? 'פג היום' : 'פג מחר'), auto: true });
    });
    // משימת הכנה אחת לכל מנה, גם כשהיא מופיעה בשני התפריטים, עם פירוט לפי תפריט
    const prep = {}, prepOrder = [];
    this.dayDishes(this.TODAY).forEach((x) => {
      if (!x.planned) return;
      if (!prep[x.name]) { prep[x.name] = { n: 0, parts: [] }; prepOrder.push(x.name); }
      prep[x.name].n += x.planned;
      prep[x.name].parts.push(x.menuLabel + ' ' + x.planned);
    });
    prepOrder.forEach((name) => openList.push({ id: 'prep-' + name, t: 'הכנה: ' + prep[name].n + ' מנות ' + name, sub: prep[name].parts.join(' · ') + ' · לפי התפריט השבועי', auto: true }));
    const closeList = [
      { id: 'c1', t: 'דיווח יומי: יצא, נשאר, נזרק', sub: 'לחיצה אחת אם הכול יצא לפי התפריט' },
      { id: 'c2', t: 'סימון תאריך פתיחה על מוצרים פתוחים' },
      { id: 'c3', t: 'ניקוי משטחים וציוד' }
    ];
    // הפשרה למחר: כל פריט קפוא שנכנס למנות של מחר בתפריט השבועי
    const thaw = {};
    this.dayDishes((this.TODAY + 1) % 5).forEach((x) => (this.recOf(x.name) || []).forEach((l) => {
      const it = this.item(l.id);
      if (it.cat !== 'קפואים' || !x.planned) return;
      const t = thaw[it.id] = thaw[it.id] || { it, amt: 0, dishes: [] };
      t.amt += x.planned * this.toBase(it, l.amt);
      if (t.dishes.indexOf(x.name) < 0) t.dishes.push(x.name);
    }));
    Object.keys(thaw).forEach((id) => {
      const t = thaw[id];
      closeList.push({ id: 'thaw-' + id, t: 'להוציא מההקפאה ' + t.it.name + ' ל' + t.dishes.join(' ול') + ' של מחר', sub: 'כ-' + this.fmtQty(t.amt, t.it) + ' · לפי התפריט השבועי', auto: true });
    });
    closeList.push({ id: 'c4', t: 'כיבוי ציוד ונעילת המקררים' });
    const group = (title, list) => {
      const items = list.map(mkItem);
      const n = items.filter((x) => x.done).length;
      return {
        title, items, progress: n + ' מתוך ' + items.length,
        bar: this.bar(n / items.length * 100, n === items.length ? '#037F4C' : '#3B4BD8'),
        all: () => this.setState((st) => { const d = JSON.parse(JSON.stringify(st.shiftDone)); list.forEach((x) => { d[k][x.id] = true; }); return { shiftDone: d }; })
      };
    };
    const tasks = [group('פתיחת משמרת', openList), group('סגירת משמרת', closeList)];

    /* הודעות */
    const annTypes = { supplier: ['החלפת ספק', 'pill p-info'], recall: ['ריקול', 'pill p-bad'], general: ['הודעה', 'pill p-neu'] };
    const kAnn = s.anns.filter((a) => a.to.indexOf(k) >= 0 && !a.reads[k]).map((a) => ({
      title: a.title, body: a.body, date: a.date,
      typeLabel: annTypes[a.type][0], cls: annTypes[a.type][1],
      style: a.urgent ? 'background:#FDECEF;border:1px solid #F2B8C3' : 'background:#EEF0FF;border:1px solid #CDD3FA',
      read: () => this.setState((st) => ({ anns: st.anns.map((x) => { if (x.id !== a.id) return x; const c = JSON.parse(JSON.stringify(x)); c.reads[k] = true; return c; }) }))
    }));
    const templates = {
      supplier: ['החלפת ספק: ', 'החל מ-[תאריך] [המוצרים] יגיעו מ"[ספק חדש]" במקום "[ספק קודם]". שעת האספקה: [שעה]. הזמנות פתוחות לספק הקודם יבוטלו אוטומטית.'],
      recall: ['ריקול: ', 'היצרן הודיע על ריקול ל[מוצר], אצווה [מספר]. יש להוציא מהמטבח את כל האריזות מהאצווה ולסמן אותן כפחת.'],
      general: ['', '']
    };
    const ann = {
      types: Object.keys(annTypes).map((t) => ({ label: annTypes[t][0], cls: 'chip' + (s.annType === t ? ' on' : ''),
        pick: () => this.setState({ annType: t, annTitle: templates[t][0], annBody: templates[t][1], annUrgent: t === 'recall' }) })),
      to: this.KITCHENS.map((x) => ({ label: x.name, cls: 'chip' + (s.annTo[x.id] ? ' on' : ''),
        toggle: () => this.setState((st) => ({ annTo: Object.assign({}, st.annTo, { [x.id]: !st.annTo[x.id] }) })) })),
      title: s.annTitle, body: s.annBody, urgent: s.annUrgent,
      setTitle: (e) => this.setState({ annTitle: e.target.value }),
      setBody: (e) => this.setState({ annBody: e.target.value }),
      toggleUrgent: () => this.setState({ annUrgent: !s.annUrgent }),
      send: () => {
        const to = this.KITCHENS.filter((x) => s.annTo[x.id]).map((x) => x.id);
        if (!to.length) { this.flash('צריך לבחור לפחות מטבח אחד'); return; }
        if (!s.annTitle.trim()) { this.flash('צריך לכתוב כותרת להודעה'); return; }
        const reads = {}; to.forEach((id) => { reads[id] = false; });
        const a = { id: 'a' + s.nextAnn, type: s.annType, title: s.annTitle, body: s.annBody, to, date: '22.10.2026, עכשיו', urgent: s.annUrgent, reads };
        this.setState((st) => ({ anns: [a].concat(st.anns), nextAnn: st.nextAnn + 1 }));
        this.flash('ההודעה נשלחה במייל למנהל/ת המטבח, ומופיעה במערכת');
      },
      sent: s.anns.map((a) => ({
        title: a.title, body: a.body, date: a.date, typeLabel: annTypes[a.type][0], cls: annTypes[a.type][1],
        reads: a.to.map((id) => ({ label: this.kitchen(id).name + (a.reads[id] ? ' ✓' : ' · לא נקרא'), cls: a.reads[id] ? 'pill p-ok' : 'pill p-low' }))
      }))
    };

    /* אתרים לסריקה */
    const siteStatus = { ok: ['נסרק', 'pill p-ok'], blocked: ['האתר חוסם סריקה', 'pill p-bad'], pending: ['בבדיקת היתכנות', 'pill p-low'] };
    const sites = {
      rows: s.sites.map((w, i) => ({
        name: w.name, url: w.url, items: w.items, last: w.last, status: siteStatus[w.status][0], cls: siteStatus[w.status][1],
        remove: () => this.setState((st) => ({ sites: st.sites.filter((x, j) => j !== i) }))
      })),
      name: s.siteName, url: s.siteUrl,
      setName: (e) => this.setState({ siteName: e.target.value }),
      setUrl: (e) => this.setState({ siteUrl: e.target.value }),
      add: () => {
        if (!s.siteName.trim() || !s.siteUrl.trim()) { this.flash('צריך שם וכתובת של האתר'); return; }
        this.setState((st) => ({ sites: st.sites.concat([{ name: st.siteName, url: st.siteUrl, items: 'ייקבע בבדיקת ההיתכנות', last: '—', status: 'pending' }]), siteName: '', siteUrl: '' }));
        this.flash('האתר נוסף לרשימה וממתין לבדיקת היתכנות');
      },
      drops: [
        { item: 'בשר בקר טחון', site: 'מחסני הבשר', price: '₪44.90 לק"ג', ours: '₪48.00', pct: '6.5%' },
        { item: 'בצל', site: 'שוק סיטונאי אונליין', price: '₪3.40 לק"ג', ours: '₪3.90', pct: '12.8%' }
      ]
    };

    /* הוספה מהירה */
    const bulkLines = this.parseBulk(s.bulkText, s.bulkCat);
    const bulk = {
      open: s.bulkOpen, text: s.bulkText,
      cats: this.CATS.map((c) => ({ v: c, cls: 'chip' + (s.bulkCat === c ? ' on' : ''), pressed: s.bulkCat === c, pick: () => this.setState({ bulkCat: c }) })),
      lines: bulkLines.map((l, i) => {
        const same = this.ITEMS.find((it) => it.name === l.name);
        return { key: i, name: l.name, qty: l.qty ? l.qty + ' ' + (same ? same.unit : l.unit) : 'בלי כמות', note: same ? 'קיים · הכמות תתווסף' : 'חדש', noteCls: same ? 'pill p-neu' : 'pill p-info' };
      }),
      hasLines: bulkLines.length > 0, none: bulkLines.length === 0,
      btn: bulkLines.length === 1 ? 'הוסף מוצר אחד' : 'הוסף ' + bulkLines.length + ' מוצרים',
      setText: (e) => this.setState({ bulkText: e.target.value }),
      toggle: () => this.setState({ bulkOpen: !s.bulkOpen, niOpen: false, countOn: false, bulkCat: s.invCat !== 'all' ? s.invCat : s.bulkCat }),
      close: () => this.setState({ bulkOpen: false }),
      save: () => {
        const r = this.addItems(s.bulkCat, bulkLines);
        this.setState({ bulkText: '', bulkOpen: false, invCat: 'all' });
        const parts = [];
        if (r.added) parts.push((r.added === 1 ? 'מוצר חדש אחד נוסף' : r.added + ' מוצרים חדשים נוספו') + ' ל' + s.bulkCat);
        if (r.merged) parts.push(r.merged === 1 ? 'למוצר קיים אחד נוספה כמות' : 'ל-' + r.merged + ' מוצרים קיימים נוספה כמות');
        this.flash(parts.join('. ') + '.');
      }
    };
    const unitOpts = ['ק"ג', 'ליטר', 'יח׳'].map((v) => ({ v }));
    const quickAdd = (c, gi) => {
      const q = s.qa[c] || { name: '', qty: '', unit: (this.CAT_DEF[c] || ['יח׳'])[0] };
      const setQa = (f) => (e) => { const v = e.target.value; this.setState((st) => ({ qa: Object.assign({}, st.qa, { [c]: Object.assign({}, st.qa[c] || q, { [f]: v }) }) })); };
      const add = () => {
        if (!q.name.trim()) { this.flash('כותבים שם מוצר ולוחצים הוסף'); return; }
        const r = this.addItems(c, [q]);
        this.setState((st) => ({ qa: Object.assign({}, st.qa, { [c]: { name: '', qty: '', unit: q.unit } }) }));
        this.flash(r.merged ? q.name.trim() + ' כבר קיים במלאי, הכמות נוספה' : q.name.trim() + ' נוסף ל' + c + '. מחיר, ספק ומינימום משלימים בלחיצה על השם.');
      };
      return {
        id: 'qa-' + gi, qtyId: 'qa-qty-' + gi, name: q.name, qty: q.qty, unit: q.unit, units: unitOpts,
        placeholder: 'מוצר חדש ב' + c + '…', aria: 'שם מוצר חדש ב' + c,
        setName: setQa('name'), setQty: setQa('qty'), setUnit: setQa('unit'), add,
        key: (e) => { if (e.key === 'Enter') { e.preventDefault(); add(); } }
      };
    };

    /* מלאי המטבח */
    const addQtyTo = (it) => {
      const n = parseFloat(s.addVals[it.id]);
      if (!(n > 0)) { this.flash('כותבים כמה ' + it.unit + ' נכנסו ולוחצים הוסף'); return; }
      const now = Math.round((s.qty[k][it.id] + n) * 10) / 10;
      this.setState((st) => {
        const qty = JSON.parse(JSON.stringify(st.qty));
        qty[k][it.id] = now;
        return { qty, addVals: Object.assign({}, st.addVals, { [it.id]: '' }) };
      });
      this.flash('נוספו ' + n + ' ' + it.unit + ' ' + it.name + '. במלאי עכשיו ' + now + ' ' + it.unit + '.');
    };
    const invRows = this.ITEMS.map((it) => {
      const q = s.qty[k][it.id];
      const st = this.stock(q, it.min);
      const low = q < it.min;
      const hasDraft = s.orders.some((o) => o.k === k && o.sup === it.sup && o.status === 'draft');
      return {
        name: it.name, cat: it.cat, unit: it.unit,
        incomplete: !it.price, editAria: 'עריכת ' + it.name,
        edit: () => this.setState({ niOpen: true, niEdit: it.id, bulkOpen: false, countOn: false,
          ni: { name: it.name, cat: it.cat, unit: it.unit, min: String(it.min), price: it.price ? String(it.price) : '', sup: it.sup, exp: String(it.exp), qty: String(q) } }),
        addVal: s.addVals[it.id] || '', addAria: 'כמות להוספה: ' + it.name,
        setAdd: (e) => { const v = e.target.value; this.setState((st) => ({ addVals: Object.assign({}, st.addVals, { [it.id]: v }) })); },
        addQty: () => addQtyTo(it),
        addKey: (e) => { if (e.key === 'Enter') { e.preventDefault(); addQtyTo(it); } },
        qtyText: q + ' ' + it.unit, minText: it.min + ' ' + it.unit,
        status: st.label, cls: st.cls,
        noOrder: !low,
        orderLabel: !low ? 'אין צורך' : hasDraft ? 'לאישור ההזמנה' : 'הזמן מהספק',
        order: () => this.orderForItem(k, it.id),
        inc: () => this.setQty(k, it.id, 1),
        dec: () => this.setQty(k, it.id, -1)
      };
    });
    const invGroups = this.CATS.filter((c) => s.invCat === 'all' || s.invCat === c).map((c) => {
      const rows = invRows.filter((r) => r.cat === c);
      const low = rows.filter((r) => !r.noOrder).length;
      return {
        key: c, name: c, rows, empty: rows.length === 0, hasRows: rows.length > 0, qa: quickAdd(c, this.CATS.indexOf(c)),
        count: rows.length === 1 ? 'פריט אחד' : rows.length + ' פריטים',
        lowText: low ? low + ' מתחת למינימום' : 'הכול תקין', lowCls: low ? 'pill p-low' : 'pill p-ok'
      };
    });
    const invCats = [['all', 'הכול']].concat(this.CATS.map((c) => [c, c])).map(([v, label]) => ({
      key: v, label: label + ' (' + (v === 'all' ? invRows.length : invRows.filter((r) => r.cat === v).length) + ')',
      cls: 'chip' + (s.invCat === v ? ' on' : ''), pressed: s.invCat === v, pick: () => this.setState({ invCat: v })
    }));

    /* תוקף */
    const expSum = { expired: 0, short: 0, week: 0, shortLabel: 'תוקף קצר (עד ' + thr + ' ימים)' };
    const expRows = this.ITEMS
      .filter((it) => s.qty[k][it.id] > 0)
      .map((it) => ({ it, d: this.daysLeft(it, k) }))
      .sort((a, b) => a.d - b.d)
      .map(({ it, d }) => {
        let status, cls;
        if (d < 0) { status = 'פג תוקף'; cls = 'pill p-bad'; expSum.expired++; }
        else if (d <= thr) { status = 'תוקף קצר'; cls = 'pill p-low'; expSum.short++; }
        else if (d <= 7) { status = 'פג השבוע'; cls = 'pill p-neu'; expSum.week++; }
        else { status = 'תקין'; cls = 'pill p-ok'; }
        const left = d < 0 ? 'פג לפני ' + (-d) + (d === -1 ? ' יום' : ' ימים') : d === 0 ? 'פג היום' : d === 1 ? 'מחר' : d + ' ימים';
        return {
          name: it.name, qtyText: s.qty[k][it.id] + ' ' + it.unit,
          date: this.dateFrom(d), left, status, cls,
          canWaste: d <= thr,
          waste: () => this.markWaste(k, it.id)
        };
      });

    /* הזמנות */
    const ordList = s.orders.filter((o) => o.k === k).slice().reverse();
    const ordRows = ordList.map((o) => {
      const total = o.lines.reduce((a, l) => a + l.qty * this.item(l.id).price, 0);
      const map = { draft: ['ממתין לאישור מנהל', 'pill p-low'], sent: ['נשלח · ממתין לקבלה', 'pill p-info'], received: ['התקבל', 'pill p-ok'] };
      return {
        num: o.num, sup: o.sup, date: o.date, src: o.src,
        lines: o.lines.map((l) => this.item(l.id).name).join(', '),
        total: this.money(total),
        status: map[o.status][0], cls: map[o.status][1],
        isDraft: o.status === 'draft', isSent: o.status === 'sent',
        send: () => this.openEmail(o),
        receive: () => this.setState({ tab: 'rec', recId: o.id })
      };
    });

    /* קבלת סחורה */
    const pending = s.orders.filter((o) => o.k === k && o.status === 'sent');
    const cur = pending.find((o) => o.id === s.recId) || pending[0];
    let rec = { has: false, none: true, pending: [], lines: [], title: '', date: '', issuesText: '', confirm: () => {} };
    if (cur) {
      let issues = 0;
      const lines = cur.lines.map((l) => {
        const it = this.item(l.id);
        let check = 'תואם', cls = 'pill p-ok';
        if (l.recv < l.qty) { check = 'חסרים ' + (l.qty - l.recv) + ' ' + it.unit; cls = 'pill p-bad'; issues++; }
        else if (l.recv > l.qty) { check = 'הגיעו ' + (l.recv - l.qty) + ' ' + it.unit + ' יותר'; cls = 'pill p-low'; issues++; }
        else if (l.inv > it.price) { check = 'מחיר גבוה מהמחירון'; cls = 'pill p-low'; issues++; }
        const chk = !!(s.recvChk[cur.id] || {})[l.id];
        return {
          name: it.name, ordered: l.qty + ' ' + it.unit, recv: l.recv + ' ' + it.unit,
          listPrice: this.money2(it.price), invPrice: this.money2(l.inv),
          check, cls, rowCls: check === 'תואם' ? '' : 'diff',
          checked: chk, aria: 'נבדק: ' + it.name,
          unit: it.unit, recvVal: l.recv, recvAria: 'כמות שהתקבלה: ' + it.name,
          setRecv: (e) => {
            const n = Math.max(0, parseFloat(e.target.value) || 0);
            this.setState((st) => ({ orders: st.orders.map((x) => {
              if (x.id !== cur.id) return x;
              const c = JSON.parse(JSON.stringify(x));
              c.lines.forEach((cl) => { if (cl.id === l.id) cl.recv = n; });
              return c;
            }) }));
          },
          toggle: () => this.setState((st) => { const r = JSON.parse(JSON.stringify(st.recvChk)); r[cur.id] = r[cur.id] || {}; r[cur.id][l.id] = !r[cur.id][l.id]; return { recvChk: r }; })
        };
      });
      const nChk = lines.filter((l) => l.checked).length;
      rec = {
        notReady: nChk < lines.length,
        confirmLabel: nChk < lines.length ? 'אשר קבלה (' + (lines.length - nChk) + ' שורות לא נבדקו)' : 'אשר קבלה ועדכן מלאי',
        markAll: () => this.setState((st) => { const r = JSON.parse(JSON.stringify(st.recvChk)); r[cur.id] = {}; cur.lines.forEach((l) => { r[cur.id][l.id] = true; }); return { recvChk: r }; }),
        has: true, none: false, lines,
        title: cur.num + ' · ' + cur.sup,
        date: cur.date,
        issuesText: issues ? issues + ' פערים מול ההזמנה' : 'הכול תואם להזמנה',
        pending: pending.map((o) => ({ label: o.num + ' · ' + o.sup, cls: 'btn sm' + (o === cur ? ' pri' : ''), pick: () => this.setState({ recId: o.id }) })),
        confirm: () => this.confirmReceive(cur.id)
      };
    }

    /* סינון תלמידים / עובדי מטה: משותף לדיווח היומי, לכמויות, למתכונים ולדוחות */
    const aud = s.aud;
    const audSeg = [{ id: 'all', label: 'הכול' }].concat(this.MENUS).map((x) => ({
      key: x.id, label: x.label, cls: aud === x.id ? 'on' : '', pressed: aud === x.id,
      // בחירת תפריט אחד מעבירה אליו גם את מודל התמחור
      pick: () => this.setState((st) => ({ aud: x.id, pmMenu: x.id === 'all' ? st.pmMenu : x.id }))
    }));
    const audName = aud === 'all' ? 'תלמידים ועובדי מטה' : this.menuLabel(aud);

    /* דיווח יומי */
    const pt = this.prodTotals(k, 'day', aud);
    const ptAll = this.prodTotals(k, 'day', 'all');
    let plannedSum = 0;
    const todayProd = this.dayProd(k, this.HISTDAYS.length - 1, aud).filter((r) => !r.virtual);
    const prodRows = todayProd.map((r) => {
      const c = r.unit;
      plannedSum += r.planned;
      return {
        key: r.key, name: r.name, slot: r.menuLabel + ' · ' + r.slot, planned: r.planned, out: r.out, left: r.left, thrown: r.thrown,
        unitCost: this.recOf(r.name) ? this.money2(c) : 'אין מתכון',
        wasteCost: this.money(r.thrown * c),
        setOut: (e) => this.setProd(k, r, 'out', e.target.value),
        setLeft: (e) => this.setProd(k, r, 'left', e.target.value),
        setThrown: (e) => this.setProd(k, r, 'thrown', e.target.value)
      };
    });

    /* פחת חומרי גלם */
    const rwIt = this.item(s.rwItem);
    const rw = {
      item: s.rwItem, amt: s.rwAmt, unit: rwIt.unit,
      options: this.ITEMS.map((it) => ({ id: it.id, label: it.name })),
      reasons: ['התקלקל', 'נשרף', 'פג תוקף', 'אחר'].map((r) => ({ label: r, cls: s.rwReason === r ? 'on' : '', pick: () => this.setState({ rwReason: r }) })),
      setItem: (e) => this.setState({ rwItem: e.target.value }),
      setAmt: (e) => this.setState({ rwAmt: e.target.value }),
      add: () => {
        const amt = Math.round((parseFloat(s.rwAmt) || 0) * 100) / 100;
        if (amt <= 0) { this.flash('צריך להזין כמות שנזרקה'); return; }
        this.setState((st) => {
          const rawWaste = JSON.parse(JSON.stringify(st.rawWaste));
          rawWaste[k].push({ id: st.rwItem, amt, reason: st.rwReason });
          const qty = JSON.parse(JSON.stringify(st.qty));
          qty[k][st.rwItem] = Math.max(0, Math.round((qty[k][st.rwItem] - amt) * 10) / 10);
          return { rawWaste, qty, rwAmt: '' };
        });
        this.flash(amt + ' ' + rwIt.unit + ' ' + rwIt.name + ' נרשמו כפחת ונגרעו מהמלאי');
      },
      rows: s.rawWaste[k].map((w) => {
        const it = this.item(w.id);
        return { name: it.name, amt: w.amt + ' ' + it.unit, reason: w.reason, cost: this.money2(w.amt * it.price) };
      })
    };

    /* צ'ק-ליסט */
    const kst = this.kStats(k);
    const checks = s.checks[k];
    let done = 0;
    const chkItems = this.CHECK.map((text, i) => {
      const auto = i === 3;
      const isDone = auto ? kst.expired === 0 : checks[i];
      if (isDone) done++;
      return {
        text, auto, done: isDone,
        autoText: kst.expired === 0 ? 'נבדק אוטומטית' : kst.expired + ' פריטים פגי תוקף',
        toggle: () => {
          if (auto) return;
          this.setState((st) => {
            const c = JSON.parse(JSON.stringify(st.checks));
            c[k][i] = !c[k][i];
            return { checks: c };
          });
        }
      };
    });

    /* תפריט השבוע לפי סוג מנה */
    const WD = ['ראשון', 'שני', 'שלישי', 'רביעי', 'חמישי', 'שישי', 'שבת'];
    const wmStart = new Date(s.wm.start + 'T00:00:00');
    const wmDates = [0, 1, 2, 3, 4].map((i) => new Date(wmStart.getFullYear(), wmStart.getMonth(), wmStart.getDate() + i));
    const dd = (d) => String(d.getDate()).padStart(2, '0') + '.' + String(d.getMonth() + 1).padStart(2, '0');
    const wmDays = wmDates.map((d, i) => ({ key: i, name: 'יום ' + WD[d.getDay()], label: 'יום ' + WD[d.getDay()] + ' ' + dd(d) }));
    // הלשונית שנערכת: תפריט תלמידים או תפריט עובדי מטה
    const wmTab = s.wmTab;
    const tabRows = this.rowsOf(wmTab);
    const tabName = this.menuLabel(wmTab);
    const setWm = (fn) => this.setState((st) => { const w = JSON.parse(JSON.stringify(st.wm)); fn(w.menus[wmTab]); return { wm: w }; });
    const addWmRow = () => {
      const name = s.wmNew.trim();
      if (!name) { this.flash('כותבים סוג מנה, למשל מרק או קינוח, ולוחצים הוסף'); return; }
      if (tabRows.some((r) => r.slot.trim() === name)) { this.flash('כבר יש בתפריט ה' + tabName + ' שורה בשם ' + name); return; }
      const w = JSON.parse(JSON.stringify(s.wm));
      w.menus[wmTab].push({ id: 'w' + s.wmNext, slot: name, cells: ['', '', '', '', ''] });
      this.setState({ wm: w, wmNext: s.wmNext + 1, wmNew: '' });
      this.flash('נוספה שורה "' + name + '" לתפריט ה' + tabName + '. ממלאים את המנות ישירות בטבלה.');
    };
    const wmBulk = this.parseMenu(s.wmBulkText);
    const wm = {
      title: 'שבוע ' + dd(wmDates[0]) + '–' + dd(wmDates[4]) + '.' + wmDates[4].getFullYear(),
      start: s.wm.start, days: wmDays,
      setStart: (e) => { const v = e.target.value; if (/^\d{4}-\d{2}-\d{2}$/.test(v)) this.setState((st) => ({ wm: Object.assign({}, st.wm, { start: v }) })); },
      tabs: this.MENUS.map((x) => ({
        key: x.id, label: x.title + ' · ' + this.rowsOf(x.id).length + ' שורות', cls: 'tab' + (wmTab === x.id ? ' on' : ''), selected: wmTab === x.id,
        pick: () => this.setState({ wmTab: x.id, wmBulkOpen: false, wmNew: '' })
      })),
      tabName,
      note: wmTab === 'stf'
        ? 'תפריט עובדי המטה: הסועדים משתנים לפי יום (משלמים ₪23 או ₪60), ועלות ארוחה למטבח ₪45. "מנת בשר" נחשבת מנה עיקרית, והסועדים מתחלקים בין המנות העיקריות.'
        : 'תפריט התלמידים: 110 סועדים ביום, משלמים ₪30, ועלות ארוחה למטבח ₪16. הסועדים מתחלקים בין המנות העיקריות.',
      rows: tabRows.map((r, ri) => ({
        key: r.id, slot: r.slot, slotAria: 'סוג מנה, שורה ' + (ri + 1) + ', תפריט ' + tabName,
        setSlot: (e) => { const v = e.target.value; setWm((rows) => { rows[ri].slot = v; }); },
        cells: r.cells.map((v, di) => ({
          key: di, v, day: wmDays[di].name, aria: (r.slot || 'מנה') + ' · ' + wmDays[di].name + ' · ' + tabName,
          set: (e) => { const x = e.target.value; setWm((rows) => { rows[ri].cells[di] = x; }); }
        })),
        del: () => { setWm((rows) => { rows.splice(ri, 1); }); this.flash('השורה "' + r.slot + '" נמחקה מתפריט ה' + tabName); },
        delAria: 'מחיקת השורה ' + r.slot
      })),
      empty: tabRows.length === 0,
      newSlot: s.wmNew,
      setNew: (e) => this.setState({ wmNew: e.target.value }),
      addRow: addWmRow,
      newKey: (e) => { if (e.key === 'Enter') { e.preventDefault(); addWmRow(); } },
      bulkOpen: s.wmBulkOpen, bulkText: s.wmBulkText,
      bulkToggle: () => this.setState({ wmBulkOpen: !s.wmBulkOpen }),
      bulkClose: () => this.setState({ wmBulkOpen: false }),
      setBulk: (e) => this.setState({ wmBulkText: e.target.value }),
      bulkLines: wmBulk.map((l, i) => {
        const ex = tabRows.some((r) => r.slot.trim() === l.slot);
        return { key: i, slot: l.slot, dishes: l.cells.map((c) => c || '—').join(' · '), note: ex ? 'עדכון' : 'חדש', noteCls: ex ? 'pill p-neu' : 'pill p-info' };
      }),
      bulkHas: wmBulk.length > 0, bulkNone: wmBulk.length === 0,
      bulkBtn: (wmBulk.length === 1 ? 'עדכן שורה אחת' : 'עדכן ' + wmBulk.length + ' שורות') + ' בתפריט ה' + tabName,
      bulkSave: () => {
        const w = JSON.parse(JSON.stringify(s.wm));
        const rows = w.menus[wmTab];
        let next = s.wmNext, upd = 0, added = 0;
        wmBulk.forEach((l) => {
          const r = rows.find((x) => x.slot.trim() === l.slot);
          if (r) { l.cells.forEach((c, i) => { if (c) r.cells[i] = c; }); upd++; }
          else { rows.push({ id: 'w' + (next++), slot: l.slot, cells: l.cells.slice() }); added++; }
        });
        this.setState({ wm: w, wmNext: next, wmBulkText: '', wmBulkOpen: false });
        const parts = [];
        if (upd) parts.push(upd === 1 ? 'שורה אחת עודכנה' : upd + ' שורות עודכנו');
        if (added) parts.push(added === 1 ? 'נוספה שורה אחת' : 'נוספו ' + added + ' שורות');
        this.flash('תפריט ה' + tabName + ' עודכן: ' + parts.join(', ') + '.');
      }
    };

    /* כמויות וחומרי גלם לפי התפריט השבועי. חומרי הגלם מחושבים לכל תפריט בנפרד ומוצגים לפי הסינון.
       ההזמנה לספקים תמיד כוללת את שני התפריטים, כדי שלא ייווצרו הזמנות כפולות או חסרות */
    const needBy = {}, noRecipe = [];
    const wqGroups = this.MENUS.map((mm) => {
      const m = mm.id, need = needBy[m] = {};
      const diners = s.wmDiners[m].map((v) => this.intVal(v));
      const rows = this.rowsOf(m).map((r) => {
        let total = 0;
        const cells = r.cells.map((dish, di) => {
          const name = dish.trim(), n = this.planPortions(m, r, di), rec = name ? this.recOf(name) : null;
          total += n;
          if (name && !rec && noRecipe.indexOf(name) < 0) noRecipe.push(name);
          if (rec) rec.forEach((l) => { const it = this.item(l.id); need[l.id] = (need[l.id] || 0) + n * this.toBase(it, l.amt); });
          const key = r.id + '_' + di, o = s.wmPortions[key];
          return {
            key: di, dish: name || '—', has: !!name, noRec: !!name && !rec,
            val: o !== undefined ? o : n, cls: 'num' + (o !== undefined && o !== '' ? ' edited' : ''),
            aria: 'מנות ' + name + ' · ' + wmDays[di].name + ' · ' + mm.label,
            set: (e) => { const v = e.target.value; this.setState((st) => ({ wmPortions: Object.assign({}, st.wmPortions, { [key]: v }) })); }
          };
        });
        return { key: r.id, slot: r.slot, cells, total: total.toLocaleString('he-IL') };
      });
      return {
        key: m, id: m, label: mm.title,
        diners: wmDays.map((d, di) => ({
          key: di, val: s.wmDiners[m][di], aria: 'סועדים ב' + d.name + ' · ' + mm.label,
          set: (e) => { const v = e.target.value; this.setState((st) => { const a = JSON.parse(JSON.stringify(st.wmDiners)); a[m][di] = v; return { wmDiners: a }; }); }
        })),
        dinersTotal: diners.reduce((a, b) => a + b, 0).toLocaleString('he-IL'),
        rows
      };
    }).filter((g) => this.menuIds(aud).indexOf(g.id) >= 0);
    const sumNeed = (ids) => { const o = {}; ids.forEach((m) => Object.keys(needBy[m]).forEach((id) => { o[id] = (o[id] || 0) + needBy[m][id]; })); return o; };
    const wqNeed = sumNeed(this.menuIds(aud)), allNeed = sumNeed(this.menuIds('all'));
    let wqCost = 0;
    const wqNeeds = this.ITEMS.filter((it) => wqNeed[it.id] > 0).map((it) => {
      const n = wqNeed[it.id], have = s.qty[k][it.id], miss = Math.max(0, n - have);
      wqCost += n * it.price;
      const parts = aud === 'all' ? this.MENUS.filter((x) => needBy[x.id][it.id] > 0).map((x) => x.label + ' ' + this.fmtQty(needBy[x.id][it.id], it)) : [];
      return {
        key: it.id, name: it.name, need: this.fmtQty(n, it), split: parts.length > 1 ? parts.join(' · ') : '', hasSplit: parts.length > 1, have: have + ' ' + it.unit,
        missing: miss > 0 ? this.fmtQty(miss, it) : '—', cost: this.money(n * it.price),
        status: miss > 0 ? 'צריך להזמין' : 'מספיק', cls: miss > 0 ? 'pill p-low' : 'pill p-ok'
      };
    });
    const wq = {
      title: 'כמויות לפי התפריט · ' + wm.title,
      range: wm.title.replace('שבוע ', ''),
      audName,
      days: wmDays,
      groups: wqGroups,
      hasEdits: Object.keys(s.wmPortions).some((x) => s.wmPortions[x] !== ''),
      resetPortions: () => { this.setState({ wmPortions: {} }); this.flash('כל הכמויות חזרו לחישוב לפי מספר הסועדים'); },
      hasMissing: noRecipe.length > 0,
      missingText: 'אין עדיין מתכון ל' + noRecipe.join(', ') + (noRecipe.length === 1 ? ', ולכן היא לא נכללת' : ', ולכן הן לא נכללות') + ' בחישוב חומרי הגלם ובעלויות. מוסיפים מתכון ומחיר במסך מתכונים ועלות מנה.',
      goRecipe: () => this.setState({ screen: 'recipes', recipeName: noRecipe[0] || s.recipeName, navOpen: false }),
      needs: wqNeeds, costTotal: this.money(wqCost), noNeeds: wqNeeds.length === 0,
      orderNote: aud === 'all' ? 'ההזמנה מאחדת את שני התפריטים, הזמנה אחת לכל ספק.' : 'מוצג רק תפריט ה' + audName + ', אבל ההזמנה תמיד מאחדת את שני התפריטים, הזמנה אחת לכל ספק.',
      order: () => {
        const lines = this.ITEMS.filter((it) => (allNeed[it.id] || 0) - s.qty[k][it.id] > 0).map((it) => ({ id: it.id, qty: Math.ceil(allNeed[it.id] - s.qty[k][it.id]) }));
        const n = this.addDrafts(k, lines, 'תפריט שבועי').length;
        if (!n) { this.flash(lines.length ? 'כבר קיימות טיוטות הזמנה לספקים האלה' : 'יש במטבח את כל מה ששני התפריטים צריכים'); return; }
        this.flash('נוצרו ' + n + ' הזמנות לפי תפריט התלמידים ותפריט עובדי המטה של ' + wm.title + '. הן ממתינות לאישור בלשונית ההזמנות.');
      }
    };

    /* מתכונים: המתכון של מנה משותף לשני התפריטים. המחיר הוא לארוחה, וכל מנה מקבלת חלק ממנו לפי הרכיב שלה */
    const mDishes = this.menuDishes(aud);
    const ri = mDishes.indexOf(s.recipeName) >= 0 ? s.recipeName : (mDishes[0] || s.recipeName);
    const recCost = this.dishCost(ri);
    const recMenus = this.dishMenus(ri).length ? this.dishMenus(ri) : this.menuIds('all');
    const kAll = this.KITCHENS.map((x) => x.id);
    // הרכיב של מנה: לפי השורה הראשונה בתפריט שהיא מופיעה בה
    const dishPart = (name, m) => {
      let p = '';
      this.menuIds(m || 'all').forEach((mm) => this.rowsOf(mm).forEach((r) => { if (!p && r.cells.some((c) => c.trim() === name)) p = this.rowPart(r); }));
      return p || 'carb';
    };
    // החלק של מנה אחת מהארוחה: לפי מה שיצא בחמשת ימי העבודה האחרונים, ואם המנה לא הוגשה, לפי משקל הרכיב
    const allocOf = (name, m) => {
      const a = this.periodAgg(kAll, 'week', m).find((x) => x.name === name);
      if (a && a.out) return a.rev / a.out;
      const part = dishPart(name, m), rows = this.rowsOf(m), present = ['main', 'carb', 'veg'].filter((p) => rows.some((r) => this.rowPart(r) === p)).concat(['sauce']);
      const W = present.reduce((x, p) => x + this.SHEET.parts[p], 0), n = Math.max(1, rows.filter((r) => this.rowPart(r) === part).length);
      return part === 'main' ? this.mealPrice(m) * this.SHEET.parts.main / W : this.mealPrice(m) * this.SHEET.parts[part] / W / n;
    };
    const lvlPill = (l) => l === 'red' ? 'pill p-bad' : l === 'orange' ? 'pill p-low' : 'pill p-ok';
    const lvlText = (l) => l === 'red' ? 'מעל הפסימי' : l === 'orange' ? 'מעל הבסיס' : 'בתוך היעד';
    const recPart = dishPart(ri), recT = this.partTarget(recPart), recLvl = this.recOf(ri) ? this.targetLvl(recCost, recPart) : '';
    const recLines = this.recOf(ri) || [];
    const setRec = (fn) => this.setState((st) => { const m = JSON.parse(JSON.stringify(st.mrec)); m[ri] = m[ri] || []; fn(m[ri]); return { mrec: m }; });
    const recAddOpts = this.ITEMS.filter((it) => !recLines.some((l) => l.id === it.id)).map((it) => ({ id: it.id, label: it.name + ' (' + it.unit + ')' }));
    const addIng = (e) => {
      const id = e.target.value;
      if (!id) return;
      const it = this.item(id);
      setRec((r) => { r.push({ id, amt: this.isUnit(it) ? 1 : 100 }); });
      this.flash(it.name + ' נוסף למתכון של ' + ri + '. מכוונים את הכמות בגרירה.');
    };
    const setMeal = (m, v) => this.setState((st) => ({ mealPrice: Object.assign({}, st.mealPrice, { [m]: v }) }));
    const recipe = {
      name: ri,
      menusText: (recMenus.length > 1 ? 'מופיעה בתפריט התלמידים ובתפריט עובדי המטה. המתכון משותף.' : 'מופיעה בתפריט ה' + this.menuLabel(recMenus[0]) + '.') + ' רכיב בארוחה: ' + this.partLabel(recPart) + '.',
      part: this.partLabel(recPart),
      target: 'יעד ל' + this.partLabel(recPart) + ' בגיליון: ' + this.money2(recT.base) + ' · פסימי ' + this.money2(recT.pess),
      targetCls: lvlPill(recLvl), targetText: this.recOf(ri) ? lvlText(recLvl) : 'אין מתכון',
      empty: recLines.length === 0,
      addOpts: recAddOpts, add: addIng,
      lines: recLines.map((l, li) => {
        const it = this.item(l.id);
        return {
          name: it.name, amt: l.amt, amtText: l.amt + ' ' + this.amtLabel(it),
          max: this.isUnit(it) ? 6 : 400, step: this.isUnit(it) ? 1 : 5,
          aria: 'כמות ' + it.name + ' למנה',
          price: this.money2(it.price) + ' ל' + (this.isUnit(it) ? 'יחידה' : it.unit),
          cost: this.money2(this.toBase(it, l.amt) * it.price),
          set: (e) => {
            const n = this.intVal(e.target.value);
            setRec((r) => { r[li].amt = n; });
          },
          del: () => setRec((r) => { r.splice(li, 1); }),
          delAria: 'הסרת ' + it.name + ' מהמתכון'
        };
      }),
      cost: this.money2(recCost),
      // מחיר הארוחה לכל תפריט שהמנה מופיעה בו, והחלק של המנה ממנו
      prices: recMenus.map((m) => {
        const meal = this.mealPrice(m), alloc = allocOf(ri, m);
        return {
          key: m, id: 'meal-price-' + m, label: m === 'stf' ? 'מחיר ארוחת עובדי מטה' : 'מחיר ארוחת תלמיד', val: meal,
          alloc: this.money2(alloc) + ' (' + this.pct(meal ? alloc / meal : 0) + ' מהארוחה)',
          profit: this.money2(alloc - recCost), profitStyle: this.plStyle(alloc - recCost),
          isStaff: m === 'stf',
          note: m !== 'stf' ? '' : this.staffAuto() ? 'אוטומטי: ' + Math.round(this.STAFF_RATE * 100) + '% ממחיר ארוחת התלמיד' : 'מחיר שהוזן ידנית',
          canReset: m === 'stf' && !this.staffAuto(),
          reset: () => this.setState((st) => { const p = Object.assign({}, st.mealPrice); delete p.stf; return { mealPrice: p }; }),
          fc: alloc ? this.pct(recCost / alloc) : '—', fcCls: alloc ? this.fcCls(recCost / alloc) : 'pill p-neu',
          set: (e) => setMeal(m, Math.max(0, parseFloat(e.target.value) || 0))
        };
      })
    };
    const only = (name) => { const ms = this.dishMenus(name); return aud === 'all' && ms.length === 1 ? ' · ' + this.menuLabel(ms[0]) : ''; };
    const recTabs = mDishes.map((name) => ({ key: name, label: name + only(name) + (this.recOf(name) ? '' : ' ⚠'), cls: ri === name ? 'on' : '', pick: () => this.setState({ recipeName: name }) }));
    // טבלת כל המנות: שורה לכל מנה בכל תפריט, עם החלק מהארוחה ויעד העלות מהגיליון
    const dishCost = [];
    this.menuIds(aud).forEach((m) => this.menuDishes(m).forEach((name) => {
      const c = this.dishCost(name), p = allocOf(name, m), part = dishPart(name, m), t = this.partTarget(part), l = this.recOf(name) ? this.targetLvl(c, part) : '';
      const fc = p ? c / p : NaN;
      dishCost.push({ key: m + '|' + name, name, menu: this.menuLabel(m), part: this.partLabel(part), menuCls: m === 'stf' ? 'pill p-pur' : 'pill p-info',
        cost: this.recOf(name) ? this.money2(c) : 'אין מתכון', price: this.money2(p), profit: this.money2(p - c), profitStyle: this.plStyle(p - c),
        fc: p ? this.pct(fc) : '—', cls: p ? this.fcCls(fc) : 'pill p-neu',
        full: this.money2(t.base) + ' · ' + this.money2(t.pess), tCls: this.recOf(name) ? lvlPill(l) : 'pill p-neu', tText: this.recOf(name) ? lvlText(l) : 'אין מתכון' });
    }));

    /* מודל תמחור מלא לארוחה, באותו מבנה כמו הגיליון. חומרי הגלם: ממוצע לארוחה בתפריט בחמשת ימי העבודה האחרונים */
    const pmS = s.pm;
    const pmMenu = s.pmMenu === 'stf' ? 'stf' : 'stu';
    const ms = this.mealStats(pmMenu);
    const recPrice = this.mealPrice(pmMenu);
    const fc = this.fullCost(ms.food);
    const pess = 1 + this.pmNum(pmS.pess) / 100;
    const sm = (n, two) => (n < 0 ? '-' : '') + (two ? this.money2(Math.abs(n)) : this.money(Math.abs(n)));
    const good = (n) => n < 0 ? 'color: #C62F4A' : 'color: #037F4C';
    const perDay = Math.max(1, this.pmNum(pmS.perDay)), pmDays = Math.max(1, this.pmNum(pmS.days)), pmMonths = Math.max(1, this.pmNum(pmS.months));
    const recNet = this.netPrice(recPrice);
    const netMeal = recNet - fc.total, netPess = recNet - fc.total * pess;
    const margin = recNet ? this.pct(netMeal / recNet) : '—';
    const contrib = recNet - fc.variable;
    const partNote = (p) => 'בגיליון ' + this.money2(this.SHEET.parts[p]) + (p === 'sauce' ? ' (קבוע לארוחה)' : ' · ממוצע מהמתכונים');
    const pmRows = this.PARTS.map(([p, label]) => ({ name: label, note: partNote(p), v: ms.per[p] })).concat([
      { name: 'חד-פעמי ואריזה', note: 'חמגשית, סכו״ם, מפית', v: fc.pack },
      { name: 'חשמל ואנרגיה', note: 'חשמל וגז להכנה', v: fc.energy },
      { name: 'אפליקציה ושירות', note: 'אפליקציה, שירות לקוחות', v: fc.app },
      { name: 'עובד חלוקה ושירות', note: 'קבוע של ' + this.money(this.pmNum(pmS.dist)) + ' בחודש, מתחלק בין הארוחות', v: fc.dist },
      { name: 'שכר עבודה במטבח', note: this.pmNum(pmS.hours) + ' שעות מתוך 8, לפי ' + this.money(this.pmNum(pmS.salary)) + ' ל-' + Math.max(1, this.pmNum(pmS.workDays)) + ' ימים', v: fc.labor }
    ]).map((r) => ({ name: r.name, note: r.note, base: this.money2(r.v), pess: this.money2(r.v * pess), share: this.pct(r.v / fc.total) }));
    const pmPeriods = [['לארוחה', 1, true], ['ליום · ' + perDay + ' ארוחות', perDay], ['לחודש · ' + pmDays + ' ימים', perDay * pmDays], ['לשנה · ' + pmMonths + ' חודשים', perDay * pmDays * pmMonths]]
      .map(([label, m, two]) => ({
        label, rev: sm(recNet * m, two), cost: sm(fc.total * m, two),
        profit: sm(netMeal * m, two), profitStyle: good(netMeal),
        pess: sm(netPess * m, two), pessStyle: good(netPess)
      }));
    const pmField = (f, label, unit, step) => ({
      id: 'pm-' + f, label, unit, step, val: pmS[f],
      set: (e) => { const v = e.target.value; this.setState((st) => ({ pm: Object.assign({}, st.pm, { [f]: v }) })); }
    });
    const pm = {
      name: pmMenu === 'stf' ? 'ארוחת עובדי מטה' : 'ארוחת תלמיד', price: this.money2(recPrice),
      menuOpts: this.MENUS.map((x) => ({ key: x.id, label: x.id === 'stf' ? 'ארוחת עובדי מטה' : 'ארוחת תלמיד', cls: pmMenu === x.id ? 'on' : '', pressed: pmMenu === x.id, pick: () => this.setState({ pmMenu: x.id }) })),
      hasMenuOpts: true,
      priceText: s.vatIn ? this.money2(recPrice) + ' כולל מע״מ, כלומר ' + this.money2(recNet) + ' הכנסה נטו' : this.money2(recPrice),
      revHead: s.vatIn ? 'הכנסות נטו' : 'הכנסות',
      vat: {
        opts: [[false, 'המחיר בלי מע״מ'], [true, 'המחיר כולל מע״מ ' + Math.round(this.VAT * 100) + '%']].map(([on, label]) => ({
          label, cls: s.vatIn === on ? 'on' : '', pressed: s.vatIn === on, pick: () => this.setState({ vatIn: on })
        })),
        note: s.vatIn
          ? 'מתוך ' + this.money2(recPrice) + ' לארוחה, ' + this.money2(recPrice - recNet) + ' הם מע״מ שמועבר לרשויות. הרווח, שיעור הרווח, נקודת האיזון והתחזית מחושבים לפי ' + this.money2(recNet) + '.'
          : 'מחיר הארוחה נחשב כולו כהכנסה, בלי ניכוי מע״מ.'
      },
      pessPct: this.pmNum(pmS.pess) + '%',
      total: this.money2(fc.total), totalPess: this.money2(fc.total * pess),
      profit: sm(netMeal, true), profitPess: sm(netPess, true), profitStyle: good(netMeal), profitPessStyle: good(netPess),
      margin, marginPess: recNet ? this.pct(netPess / recNet) : '—',
      breakeven: contrib > 0 ? Math.ceil(fc.fixedDay / contrib).toLocaleString('he-IL') + ' ארוחות' : 'אין',
      breakevenNote: contrib > 0 ? 'ביום, כדי לכסות שכר ועובד חלוקה' : 'המחיר לא מכסה את העלויות המשתנות',
      rows: pmRows, periods: pmPeriods,
      fields: [
        pmField('pack', 'חד-פעמי ואריזה', '₪ לארוחה', 0.05),
        pmField('energy', 'חשמל ואנרגיה', '₪ לארוחה', 0.05),
        pmField('app', 'אפליקציה ושירות', '₪ לארוחה', 0.1),
        pmField('dist', 'עובד חלוקה ושירות', '₪ לחודש', 100),
        pmField('salary', 'עלות שכר במטבח', '₪ לחודש', 1000),
        pmField('workDays', 'ימי עבודה לחישוב השכר', 'ימים בחודש', 1),
        pmField('hours', 'שעות עבודה על הארוחות', 'מתוך יום של 8 שעות', 0.5),
        pmField('perDay', 'ארוחות ביום', 'ארוחות', 10),
        pmField('days', 'ימי פעילות בחודש', 'ימים', 1),
        pmField('months', 'חודשי פעילות בשנה', 'חודשים', 1),
        pmField('pess', 'תרחיש פסימי', '% תוספת לכל העלויות', 5)
      ],
      reset: () => { this.setState({ pm: Object.assign({}, this.PM) }); this.flash('הפרמטרים חזרו לערכי מודל התמחור'); }
    };

    /* ספקים */
    const pctThr = s.settings.cheaperPct / 100;
    const supNames = [];
    this.ITEMS.forEach((it) => { if (supNames.indexOf(it.sup) < 0) supNames.push(it.sup); });
    const suppliers = supNames.map((name) => {
      const its = this.ITEMS.filter((it) => it.sup === name);
      const purchases = s.orders.filter((o) => o.sup === name && o.status !== 'draft')
        .reduce((a, o) => a + o.lines.reduce((b, l) => b + l.recv * l.inv, 0), 0);
      return { name, cat: its[0].cat, items: its.length, purchases: this.money(purchases), email: this.supEmail(name), canRemove: false };
    });
    s.extraSups.forEach((e) => {
      if (supNames.indexOf(e.name) >= 0) return;
      suppliers.push({
        name: e.name, cat: e.cat, items: Object.keys(e.prices).length, purchases: this.money(0), email: e.email || '[אימייל הספק]',
        canRemove: true, removeAria: 'הסרת הספק ' + e.name,
        remove: () => { this.saveExtraSups(this.state.extraSups.filter((x) => x.name !== e.name)); this.flash('הספק ' + e.name + ' הוסר'); }
      });
    });
    const addSup = () => this.openSupForm();
    const priceRows = this.ITEMS.map((it) => {
      const ch = it.prev ? (it.price - it.prev) / it.prev : 0;
      const best = this.altsFor(it).find((a) => a.price != null) || { name: it.alt, price: it.altPrice };
      const save = it.price ? (it.price - best.price) / it.price : 0;
      let rec = 'הספק הנוכחי משתלם', recCls = 'pill p-neu';
      if (save >= pctThr && save > 0) { rec = 'זול ב-' + this.pct(save) + ' אצל החלופי'; recCls = 'pill p-info'; }
      else if (save > 0) { rec = 'זול במעט (' + this.pct(save) + ')'; recCls = 'pill p-neu'; }
      return {
        name: it.name + ' (' + it.unit + ')', sup: it.sup, price: this.money2(it.price),
        chg: ch === 0 ? 'ללא שינוי' : (ch > 0 ? '+' : '') + this.pct(ch),
        chgCls: ch > 0 ? 'pill p-low' : ch < 0 ? 'pill p-ok' : 'pill p-neu',
        alt: best.name, altPrice: this.money2(best.price), rec, recCls,
        canSwitch: save >= pctThr && save > 0, noSwitch: !(save >= pctThr && save > 0),
        switchAria: 'מעבר לספק חלופי עבור ' + it.name, openSwitch: () => this.openSwitch(it.id)
      };
    });
    const schedules = s.schedules.map((m, i) => ({
      title: m.title, to: m.to, freq: m.freq, next: m.on ? m.next : '—',
      status: m.on ? 'פעיל' : 'מושהה', cls: m.on ? 'pill p-ok' : 'pill p-neu',
      btn: m.on ? 'השהה' : 'הפעל',
      toggle: () => this.setState((st) => ({ schedules: st.schedules.map((x, j) => j === i ? Object.assign({}, x, { on: !x.on }) : x) }))
    }));

    /* התראות */
    const aRows = [];
    let aExp = 0, aQty = 0, aPrice = 0;
    this.KITCHENS.forEach((kk) => {
      this.ITEMS.forEach((it) => {
        const q = s.qty[kk.id][it.id];
        const d = this.daysLeft(it, kk.id);
        if (q > 0 && d <= thr) {
          aExp++;
          aRows.push({ order: d, type: d < 0 ? 'פג תוקף' : 'תוקף', cls: d < 0 ? 'pill p-bad' : 'pill p-low',
            text: q + ' ' + it.unit + ' ' + it.name + (d < 0 ? ' פגו לפני ' + (-d) + ' ימים' : d === 0 ? ' פגים היום' : d === 1 ? ' פגים מחר' : ' פגים בעוד ' + d + ' ימים'),
            where: kk.name, btn: 'לניהול התוקף', go: () => openKitchen(kk.id, 'exp') });
        }
        if (q < it.min) {
          aQty++;
          const hasDraft = s.orders.some((o) => o.k === kk.id && o.sup === it.sup && o.status === 'draft');
          const hasSent = s.orders.some((o) => o.k === kk.id && o.status === 'sent' && o.lines.some((l) => l.id === it.id));
          aRows.push({ order: 50, type: q === 0 ? 'אזל' : 'כמות נמוכה', cls: q === 0 ? 'pill p-bad' : 'pill p-low',
            text: it.name + ': ' + q + ' ' + it.unit + ' במלאי, מתחת למינימום של ' + it.min + (hasSent ? '. כבר הוזמן ובדרך.' : ''),
            where: kk.name,
            btn: hasSent ? 'למלאי המטבח' : hasDraft ? 'לאישור ההזמנה' : 'הכן מייל לספק',
            go: hasSent ? () => openKitchen(kk.id, 'inv') : () => this.orderForItem(kk.id, it.id) });
        }
      });
    });
    this.ITEMS.forEach((it) => {
      const save = it.price ? (it.price - it.altPrice) / it.price : 0;
      if (save >= pctThr && save > 0) {
        aPrice++;
        aRows.push({ order: 100, type: 'מחיר זול יותר', cls: 'pill p-info',
          text: it.name + ' זול ב-' + this.pct(save) + ' אצל ' + it.alt + ' (' + this.money2(it.altPrice) + ' במקום ' + this.money2(it.price) + ')',
          where: 'ספקים', btn: 'להשוואת מחירים', go: go('suppliers') });
      }
    });
    let aApprove = 0;
    s.orders.filter((o) => o.status === 'draft').forEach((o) => {
      aApprove++;
      aRows.push({ order: -10, type: 'ממתין לאישור', cls: 'pill p-pur',
        text: 'מייל הזמנה ' + o.num + ' אל ' + o.sup + ' (' + o.lines.length + ' פריטים) מוכן ומחכה לאישור שליחה',
        where: this.kitchen(o.k).name, btn: 'תצוגה ואישור', go: () => this.openEmail(o) });
    });
    const plA = this.plAlerts();
    plA.forEach((a) => {
      aRows.push({ order: a.level === 'red' ? -20 : 20, type: a.tag, cls: a.cls, text: a.text, where: a.where, btn: 'לדוח ההשוואה',
        go: () => this.setState({ screen: 'reports', aud: a.aud, navOpen: false }) });
    });
    this.dayAlerts().forEach((a) => aRows.push({ order: a.mood === 'sad' ? -30 : 40, type: a.tag, cls: a.cls, text: a.short, where: a.where, btn: a.btn, go: a.go }));
    const over = { red: [], orange: [] };
    this.menuIds('all').forEach((m) => this.rowsOf(m).forEach((r) => {
      const part = this.rowPart(r);
      r.cells.forEach((c) => {
        const n = c.trim();
        if (!n || !this.recOf(n)) return;
        const l = this.targetLvl(this.dishCost(n), part), label = n + ' ' + this.money2(this.dishCost(n));
        if (l && over[l].indexOf(label) < 0) over[l].push(label);
      });
    }));
    [['red', 'pill p-bad', 30, 'מעל היעד הפסימי בגיליון (+50%)'], ['orange', 'pill p-low', 70, 'מעל יעד הבסיס בגיליון']].forEach(([l, cls, order, what]) => {
      if (!over[l].length) return;
      aRows.push({ order, type: 'עלות מתכון', cls, text: over[l].length + ' מנות ' + what + ': ' + over[l].join(', ') + '. יעד לרכיב: מנה עיקרית ₪4.60, פחמימה ₪1.50, ירקות ₪0.50.',
        where: 'מתכונים', btn: 'למתכונים', go: () => this.setState({ screen: 'recipes', navOpen: false }) });
    });
    aRows.sort((a, b) => a.order - b.order);
    const set = {
      expDays: s.settings.expDays, cheaperPct: s.settings.cheaperPct,
      gnomeAuto: s.gnomeAuto, toggleGnomeAuto: () => this.gnomeToggleAuto(),
      setExp: (e) => { const n = this.intVal(e.target.value); this.setState((st) => ({ settings: Object.assign({}, st.settings, { expDays: n }) })); },
      setPct: (e) => { const n = this.intVal(e.target.value); this.setState((st) => ({ settings: Object.assign({}, st.settings, { cheaperPct: n }) })); }
    };

    const fire = (id) => () => this.gnomeSimulate(id);
    const sim = {
      open: fire('idle'),
      groups: [['day', 'שגרה'], ['bad', 'יום רע'], ['good', 'יום מצוין']].map(([key, label]) => ({
        key, label, items: this.simItems().filter((x) => x.group === key).map((x) => ({ key: x.id, label: x.label, dot: 'gdot ' + x.c, fire: fire(x.id) }))
      }))
    };

    /* מייל לספק לאישור */
    const eo = s.orders.find((o) => o.id === s.emailOrderId && o.status === 'draft');
    let em = { open: false, lines: [] };
    if (eo) {
      const ek = this.kitchen(eo.k);
      let etot = 0;
      const elines = eo.lines.map((l, li) => {
        const it = this.item(l.id);
        etot += l.qty * it.price;
        return {
          name: it.name, unit: it.unit, qty: l.qty, price: this.money2(it.price), total: this.money(l.qty * it.price),
          aria: 'כמות ' + it.name,
          set: (e) => {
            const n = this.intVal(e.target.value);
            this.setState((st) => ({ orders: st.orders.map((x) => {
              if (x.id !== eo.id) return x;
              const c = JSON.parse(JSON.stringify(x));
              c.lines[li].qty = n; c.lines[li].recv = n;
              return c;
            }) }));
          }
        };
      });
      em = {
        open: true, num: eo.num, sup: eo.sup, kitchen: ek.name, src: eo.src,
        from: ek.name + ' · [כתובת המייל של המטבח]',
        to: eo.sup + ' · [אימייל הספק]',
        subject: 'הזמנה ' + eo.num + ' · ' + ek.name,
        lines: elines, total: this.money(etot),
        body: s.emailBody,
        setBody: (e) => this.setState({ emailBody: e.target.value }),
        refresh: () => this.setState({ emailBody: this.emailBody(eo) }),
        close: () => this.setState({ emailOrderId: null }),
        later: () => { this.setState({ emailOrderId: null }); this.flash('ההזמנה נשמרה וממתינה לאישור במסך ההתראות'); },
        approve: () => {
          this.setState((st) => ({ emailOrderId: null, orders: st.orders.map((x) => x.id === eo.id ? Object.assign({}, x, { status: 'sent' }) : x) }));
          this.flash('אושר ונשלח. המייל יצא אל ' + eo.sup + ', וההזמנה ממתינה לקבלת סחורה.');
        }
      };
    }

    /* מעבר לספק חלופי */
    let sw = { open: false, opts: [], scopes: [] };
    if (s.swId) {
      const it = this.item(s.swId);
      const regen = (patch) => {
        const n = Object.assign({ swAlt: s.swAlt, swQty: s.swQty, swScope: s.swScope }, patch);
        this.setState(Object.assign(patch, { swNew: this.swNewMail(it, n.swAlt, n.swQty), swCancel: this.swCancelMail(it, n.swScope) }));
      };
      // רק ספקים שמספקים את הפריט או מוצרים מאותו סוג (מחלבה לא מוכרת בשר)
      const names = this.altsFor(it).map((a) => a.name);
      const p = this.swPrice(it, s.swAlt);
      sw = {
        open: true, name: it.name, unit: it.unit, sup: it.sup, price: this.money2(it.price), qty: s.swQty,
        opts: names.map((n) => {
          const np = this.swPrice(it, n);
          return {
            name: n, cls: 'swopt' + (s.swAlt === n ? ' on' : ''), pressed: s.swAlt === n,
            note: np != null ? this.money2(np) + ' ל' + it.unit + (np < it.price ? ' · חיסכון ' + this.pct((it.price - np) / it.price) : '') : 'יתבקש מחיר במייל',
            pick: () => regen({ swAlt: n })
          };
        }),
        scopes: [['item', 'רק הפריט הזה'], ['all', 'סיום כל ההתקשרות']].map(([v, label]) => ({
          label, cls: s.swScope === v ? 'on' : '', pressed: s.swScope === v, pick: () => regen({ swScope: v })
        })),
        saving: p != null && p < it.price ? 'חיסכון משוער: ' + this.money((it.price - p) * s.swQty) + ' בחודש' : '',
        setQty: (e) => regen({ swQty: this.intVal(e.target.value) }),
        newTo: s.swAlt + ' · ' + this.supEmail(s.swAlt), newSubject: 'בקשה להתחלת אספקה: ' + it.name + ' · ' + this.KITCHENS[0].name,
        cancelTo: it.sup + ' · ' + this.supEmail(it.sup),
        cancelSubject: (s.swScope === 'all' ? 'הודעה על סיום התקשרות' : 'עדכון: הפסקת רכישת ' + it.name) + ' · ' + this.KITCHENS[0].name,
        newBody: s.swNew, cancelBody: s.swCancel,
        setNew: (e) => this.setState({ swNew: e.target.value }),
        setCancel: (e) => this.setState({ swCancel: e.target.value }),
        close: () => this.setState({ swId: null }),
        approve: () => this.approveSwitch()
      };
    }

    /* הוספת ספק */
    let sf = { open: false, cats: [], rows: [] };
    if (s.supOpen && s.supForm) {
      const f = s.supForm;
      const setF = (patch) => this.setState((st) => ({ supForm: Object.assign({}, st.supForm, patch) }));
      sf = {
        open: true, name: f.name, email: f.email, cat: f.cat,
        setName: (e) => setF({ name: e.target.value }),
        setEmail: (e) => setF({ email: e.target.value }),
        cats: this.CATS.map((c) => ({ label: c, value: c, selected: f.cat === c })),
        setCat: (e) => setF({ cat: e.target.value, prices: {} }),
        rows: this.ITEMS.filter((it) => it.cat === f.cat).map((it) => ({
          name: it.name, unit: it.unit, cur: this.money2(it.price) + ' אצל ' + it.sup, value: f.prices[it.id] || '',
          aria: 'מחיר ' + it.name + ' אצל הספק החדש',
          set: (e) => { const v = e.target.value; this.setState((st) => ({ supForm: Object.assign({}, st.supForm, { prices: Object.assign({}, st.supForm.prices, { [it.id]: v }) }) })); }
        })),
        close: () => this.setState({ supOpen: false, supForm: null }),
        save: () => this.saveSupForm()
      };
    }

    /* חשבוניות */
    let invTotal = 0, invWaiting = 0, invGaps = 0;
    const invRowsList = s.invoices.map((iv) => {
      invTotal += iv.amount;
      if (!iv.fwd) invWaiting++;
      if (iv.match === 'gap') invGaps++;
      return {
        num: iv.num, sup: iv.sup, kitchen: this.kitchen(iv.k).name, date: iv.date,
        amount: this.money(iv.amount),
        match: iv.match === 'ok' ? 'תואם' : 'יש פער',
        matchCls: iv.match === 'ok' ? 'pill p-ok' : 'pill p-low',
        canFwd: !iv.fwd, isFwd: !!iv.fwd, fwdText: 'הועבר ' + iv.fwd,
        fwd: () => { this.setState((st) => ({ invoices: st.invoices.map((x) => x.id === iv.id ? Object.assign({}, x, { fwd: '22.10' }) : x) })); this.flash('החשבונית ' + iv.num + ' נשלחה במייל להנהלת החשבונות ברשת אמית'); }
      };
    });

    /* דוחות: הכול מחושב מהתפריט השבועי ומהדיווח היומי */
    const repPer = s.period;
    const repDay = s.repDay !== undefined ? s.repDay : this.HISTDAYS.length - 1, repDayArg = repPer === 'day' ? repDay : undefined;
    const rawMult = { day: 1, week: this.HISTDAYS.length, month: this.MONTH_DAYS }[repPer];
    const kIds = s.repK === 'all' ? this.KITCHENS.map((x) => x.id) : [s.repK];
    let rRev = 0, rCost = 0, rWaste = 0, rRaw = 0;
    const kTot = kIds.map((id) => { const t = this.prodTotals(id, repPer, aud, repDayArg); rRev += t.rev; rCost += t.cost; rWaste += t.waste; rRaw += t.rawCost; return { id, t }; });
    const maxRev = Math.max.apply(null, kTot.map((x) => x.t.rev)) || 1;
    const kbars = kTot.map(({ id, t }) => ({
      name: this.kitchen(id).name,
      rev: this.money(t.rev), cost: this.money(t.cost), profit: this.money(t.rev - t.cost),
      revBar: this.bar(t.rev / maxRev * 100, '#3B4BD8'),
      costBar: this.bar(t.cost / maxRev * 100, '#F2994A')
    }));
    const dishAgg = this.periodAgg(kIds, repPer, aud, repDayArg);
    // שבוע העבודה יום אחר יום: תלמידים, עובדי מטה, וסה״כ לפי הסינון
    const wkSum = { stu: 0, stf: 0, rev: 0, cost: 0 };
    const wkRows = this.HISTDAYS.map((h, di) => {
      const meals = {}; let rev = 0, cost = 0;
      this.MENUS.forEach((mm) => { meals[mm.id] = 0; });
      kIds.forEach((id) => this.dayProd(id, di, aud).forEach((r) => {
        rev += r.rev; cost += (r.out + r.left + r.thrown) * r.unit;
        if (r.part === 'main') meals[r.menu] += r.out;
      }));
      wkSum.stu += meals.stu; wkSum.stf += meals.stf; wkSum.rev += rev; wkSum.cost += cost;
      const on = repDay === di;
      return {
        key: di, label: h.label, stu: meals.stu ? meals.stu.toLocaleString('he-IL') : '—', stf: meals.stf ? meals.stf.toLocaleString('he-IL') : '—',
        meals: (meals.stu + meals.stf).toLocaleString('he-IL'), rev: this.money(rev), cost: this.money(cost),
        profit: this.money(rev - cost), profitStyle: this.plStyle(rev - cost, 'font-weight: 700; '),
        rowCls: on ? 'dayon' : '', btnCls: on ? 'on' : '', pressed: on, pick: () => this.setState({ repDay: di })
      };
    });
    const plSum = { out: 0, rev: 0, prepared: 0, cost: 0 };
    const plRows = dishAgg.map((x) => {
      const rev = x.rev;
      const cost = x.cost;
      if (!x.virtual) { plSum.out += x.out; plSum.prepared += x.prepared; }
      plSum.rev += rev; plSum.cost += cost;
      return {
        key: x.name, name: x.name, out: x.out.toLocaleString('he-IL'), price: x.out ? this.money2(rev / x.out) : '—', menus: (x.virtual ? 'חלק מהארוחה · ' : this.partLabel(x.part) + ' · ') + x.menus.map((m) => this.menuLabel(m)).join(' + '), rev: this.money(rev),
        prepared: x.prepared.toLocaleString('he-IL'), unitCost: x.virtual || this.recOf(x.name) ? this.money2(x.unit) : 'אין מתכון', cost: this.money(cost), profit: this.money(rev - cost), profitStyle: this.plStyle(rev - cost, 'font-weight: 700; ')
      };
    });
    // המנות הפופולריות: מנות עיקריות בלבד, כי תוספת יוצאת לכל סועד
    const mainAgg = dishAgg.some((x) => x.main) ? dishAgg.filter((x) => x.main) : dishAgg;
    const maxOut = Math.max.apply(null, mainAgg.map((x) => x.out)) || 1;
    const popular = mainAgg.slice().sort((a, b) => b.out - a.out).map((x, i) => ({
      key: x.name, rank: i + 1, name: x.name, out: x.out.toLocaleString('he-IL'),
      bar: this.bar(x.out / maxOut * 100, i === 0 ? '#3B4BD8' : '#8C95E8')
    }));
    const wasteRows = dishAgg.filter((x) => !x.virtual).sort((a, b) => b.thrown * b.unit - a.thrown * a.unit).map((x) => {
      const p = x.prepared ? x.thrown / x.prepared : 0;
      return { key: x.name, name: x.name, thrown: x.thrown.toLocaleString('he-IL'), pct: this.pct(p), cls: p > 0.05 ? 'pill p-bad' : p > 0.03 ? 'pill p-low' : 'pill p-ok', cost: this.money(x.thrown * x.unit) };
    });
    const rawAgg = {};
    kIds.forEach((id) => s.rawWaste[id].forEach((w) => { rawAgg[w.id] = (rawAgg[w.id] || 0) + w.amt; }));
    const rawRows = Object.keys(rawAgg).map((id) => {
      const it = this.item(id);
      return { name: it.name, amt: this.fmtQty(rawAgg[id] * rawMult, it), cost: this.money(rawAgg[id] * rawMult * it.price), v: rawAgg[id] * it.price };
    }).sort((a, b) => b.v - a.v);
    // מעקב פופולריות: חמשת ימי העבודה האחרונים, המנות העיקריות של כל יום לפי התפריט השבועי
    const popNames = [];
    const popCols = this.HISTDAYS.map((h, d) => {
      const col = {};
      kIds.forEach((id) => {
        const rows = this.dayProd(id, d, aud);
        const pool = rows.some((x) => x.main) ? rows.filter((x) => x.main) : rows;
        pool.forEach((x) => { col[x.name] = (col[x.name] || 0) + x.out; if (popNames.indexOf(x.name) < 0) popNames.push(x.name); });
      });
      return col;
    });
    const colMax = popCols.map((col) => Math.max.apply(null, Object.keys(col).map((n) => col[n]).concat([0])));
    const popTotals = {};
    popNames.forEach((n) => { popTotals[n] = popCols.reduce((a, col) => a + (col[n] || 0), 0); });
    const popOrder = popNames.slice().sort((a, b) => popTotals[b] - popTotals[a]);
    const pop = {
      days: this.HISTDAYS.map((h, d) => ({ key: d, label: d === this.HISTDAYS.length - 1 ? h.label + ' · היום' : h.label })),
      rows: popOrder.map((n, rank) => ({
        key: n, name: n,
        cells: popCols.map((col, d) => ({ key: d, v: col[n] ? col[n].toLocaleString('he-IL') : '—', cls: col[n] && col[n] === colMax[d] ? 'top' : '' })),
        total: popTotals[n].toLocaleString('he-IL'),
        rank: rank + 1, rankCls: rank === 0 ? 'pill p-ok' : rank < 3 ? 'pill p-info' : 'pill p-neu'
      })),
      leaders: popCols.map((col, d) => ({ key: d, name: Object.keys(col).find((n) => col[n] === colMax[d] && colMax[d] > 0) || '—' })),
      leader: popOrder[0] || '—'
    };
    /* השוואת רווח והפסד לפי שבועות ולפי חודשים */
    const chgCell = (v, l) => v === undefined
      ? { text: '—', cls: 'muted' }
      : { text: v <= -1 ? '▼ עבר להפסד' : (v < 0 ? '▼ ' : '▲ ') + this.pct(Math.abs(v)), cls: l === 'red' ? 'pill p-bad' : l === 'orange' ? 'pill p-low' : '' };
    const lvlNote = (l) => l === 'red' ? 'קריטי: ירידה של יותר מ-25%' : l === 'orange' ? 'התראה: ירידה של יותר מ-12.5%' : '';
    const trendTable = (rows) => rows.slice().reverse().map((r) => ({
      key: r.i, label: r.label + (r.current ? ' · נוכחי' : ''), note: lvlNote(r.lvl), hasNote: !!r.lvl,
      rev: this.money(r.rev), cost: this.money(r.cost), profit: this.money(r.profit), profitStyle: this.plStyle(r.profit, 'font-weight: 700; '),
      revChg: chgCell(r.revChg, r.revLvl), profitChg: chgCell(r.profitChg, r.profitLvl),
      rowCls: r.lvl === 'red' ? 'crit' : r.lvl === 'orange' ? 'warn' : ''
    }));
    const trendCard = (type) => {
      const rows = this.trendRows(type, aud);
      const unit = type === 'week' ? 'השבועות' : 'החודשים';
      const nAlert = rows.filter((r) => r.lvl).length;
      return {
        key: type,
        title: type === 'week' ? 'השוואת רווח והפסד לפי שבועות' : 'השוואת רווח והפסד לפי חודשים',
        sub: (type === 'week' ? '12 השבועות האחרונים, 5 ימי עבודה בכל שבוע' : '8 החודשים האחרונים. אוקטובר הוא צפי לפי השבוע האחרון') + ' · ' + audName +
          '. כל תקופה מושווית לממוצע 4 ' + unit + ' שלפניה.',
        alertText: nAlert ? nAlert + (nAlert === 1 ? ' תקופה עם ירידה' : ' תקופות עם ירידה') : 'אין ירידות חריגות',
        alertCls: rows.some((r) => r.lvl === 'red') ? 'pill p-bad' : nAlert ? 'pill p-low' : 'pill p-ok',
        chart: this.trendChart(rows, type, s.trendHover, s.trendView[type]),
        aria: (type === 'week' ? 'גרף רווח והפסד לפי שבועות' : 'גרף רווח והפסד לפי חודשים') + '. הנתונים המלאים בטבלה שמתחת.',
        rows: trendTable(rows),
        mail: () => this.setState({ rptMail: type, trendHover: null })
      };
    };
    const trends = [trendCard('week'), trendCard('month')];

    /* תצוגה מקדימה של הדוח במייל. בדמו לא נשלח מייל בפועל */
    let rm = { open: false };
    if (s.rptMail) {
      const type = s.rptMail, wk = type === 'week';
      const all = this.trendRows(type, 'all'), cur = all[all.length - 1];
      const summary = ['all'].concat(this.MENUS.map((x) => x.id)).map((a) => {
        const rr = this.trendRows(type, a), c = rr[rr.length - 1];
        return { key: a, name: a === 'all' ? 'כל המטבח' : this.MENUS.find((x) => x.id === a).title, rev: this.money(c.rev), cost: this.money(c.cost), profit: this.money(c.profit), profitStyle: this.plStyle(c.profit, 'font-weight: 700; '), revChg: chgCell(c.revChg, c.revLvl), profitChg: chgCell(c.profitChg, c.profitLvl), rowCls: c.lvl === 'red' ? 'crit' : c.lvl === 'orange' ? 'warn' : '' };
      });
      const al = this.plAlerts().filter((a) => a.type === type);
      rm = {
        open: true,
        title: wk ? 'דוח רווח והפסד שבועי' : 'דוח רווח והפסד חודשי',
        types: [['week', 'דוח שבועי'], ['month', 'דוח חודשי']].map(([t, label]) => ({ key: t, label, cls: type === t ? 'on' : '', pressed: type === t, pick: () => this.setState({ rptMail: t, trendHover: null }) })),
        from: 'Smart Kitchen · דוחות אוטומטיים',
        to: 'הנהלת רשת אמית; ' + kit.manager + ' (מנהל/ת המטבח)',
        subject: (wk ? 'דוח שבועי' : 'דוח חודשי') + ' · רווח והפסד · ' + kit.name + ' · ' + cur.label,
        kitchen: kit.name, period: cur.label,
        hasAlerts: al.length > 0, noAlerts: al.length === 0,
        alertsTitle: al.some((a) => a.level === 'red') ? 'נורה אדומה: יש ירידה קריטית' : 'שימו לב: יש ירידה',
        alertsStyle: al.some((a) => a.level === 'red') ? 'background: #FDECEF; border: 1px solid #F2B8C3' : 'background: #FFF4E5; border: 1px solid #F6D3A1',
        alerts: al.map((a) => ({ key: a.key, tag: a.tag, cls: a.cls, text: a.text })),
        summary,
        chart: this.trendChart(all, 'mail-' + type, s.trendHover, s.trendView[type]),
        rows: trendTable(all),
        footer: (wk ? 'הדוח השבועי נשלח אוטומטית בכל יום חמישי בסוף היום.' : 'הדוח החודשי נשלח אוטומטית ב-1 בכל חודש.') + ' ההשוואה היא מול ממוצע 4 ה' + (wk ? 'שבועות' : 'חודשים') + ' הקודמים: ירידה של יותר מ-12.5% מסומנת בכתום, ויותר מ-25% באדום.',
        close: () => this.setState({ rptMail: null, trendHover: null }),
        backdrop: (e) => { if (e.target === e.currentTarget) this.setState({ rptMail: null, trendHover: null }); },
        send: () => {
          this.setState({ rptMail: null, trendHover: null });
          this.flash((wk ? 'הדוח השבועי' : 'הדוח החודשי') + ' נשלח להנהלת הרשת ולמנהל/ת המטבח. בדמו לא נשלח מייל בפועל.');
        }
      };
    }

    /* השוואה למודל התמחור בגיליון: לארוחה, בסיס ופסימי מול מה שקרה בפועל בחמשת ימי העבודה האחרונים */
    const SH = this.SHEET, shP = 1 + SH.pess;
    const opMeal = (() => { const f = this.fullCost(0); return f.pack + f.energy + f.app + f.dist + f.labor; })();
    const act = {};
    this.MENUS.forEach((x) => { const st = this.mealStats(x.id); act[x.id] = Object.assign(st, { op: opMeal, total: st.food + opMeal, net: st.revPerMeal - st.food - opMeal }); });
    // עלות: מעל הפסימי אדום, מעל הבסיס כתום. רווח: מתחת לפסימי אדום, מתחת לבסיס כתום
    const costCell = (v, base) => ({ text: this.money2(v), cls: !base ? '' : v > base * shP + 0.005 ? 'pill p-bad' : v > base + 0.005 ? 'pill p-low' : '' });
    const gainCell = (v, base, pessV) => ({ text: (v < 0 ? '-' : '') + this.money2(Math.abs(v)), cls: v < pessV - 0.005 ? 'pill p-bad' : v < base - 0.005 ? 'pill p-low' : '', style: v < base - 0.005 ? '' : this.plStyle(v) });
    const cmpRow = (key, name, base, pessV, a, kind, bold) => ({
      key, name, nameStyle: bold ? 'font-weight: 700' : 'font-weight: 400; padding-inline-start: 26px', base: this.money2(base), pess: this.money2(pessV),
      cells: this.MENUS.map((x) => {
        const v = a(act[x.id]);
        const c = kind === 'gain' ? gainCell(v, base, pessV) : kind === 'price' ? { text: this.money2(v), cls: '' } : costCell(v, base);
        return Object.assign({ key: x.id }, c);
      })
    });
    const sheetCmp = {
      cols: this.MENUS.map((x) => ({ key: x.id, label: 'בפועל · ' + (x.id === 'stf' ? 'ארוחת עובדי מטה' : 'ארוחת תלמיד') })),
      rows: [
        cmpRow('price', 'מחיר לארוחה', SH.price, SH.price, (x) => x.revPerMeal, 'price', true),
        cmpRow('main', 'מנה עיקרית', SH.parts.main, SH.parts.main * shP, (x) => x.per.main),
        cmpRow('carb', 'פחמימה', SH.parts.carb, SH.parts.carb * shP, (x) => x.per.carb),
        cmpRow('veg', 'ירקות', SH.parts.veg, SH.parts.veg * shP, (x) => x.per.veg),
        cmpRow('sauce', 'רטבים ותבלינים', SH.parts.sauce, SH.parts.sauce * shP, (x) => x.per.sauce),
        cmpRow('food', 'סה״כ חומרי גלם', SH.total - SH.op, (SH.total - SH.op) * shP, (x) => x.food, 'cost', true),
        cmpRow('op', 'עלויות תפעול (אריזה, חשמל, אפליקציה, חלוקה, שכר)', SH.op, SH.op * shP, (x) => x.op),
        cmpRow('total', 'סה״כ עלות לארוחה', SH.total, SH.total * shP, (x) => x.total, 'cost', true),
        cmpRow('net', 'רווח נקי לארוחה', SH.net, SH.price - SH.total * shP, (x) => x.net, 'gain', true)
      ],
      note: 'בפועל: ממוצע לארוחה בחמשת ימי העבודה האחרונים (' + this.HISTDAYS[0].label + '–' + this.HISTDAYS[this.HISTDAYS.length - 1].label + '). עלויות התפעול לפי הפרמטרים במודל התמחור. ' +
        'בכתום: עלות מעל הבסיס או רווח מתחתיו. באדום: מעבר לתרחיש הפסימי. הגיליון בנוי לארוחת תלמיד ב-₪30; ארוחת עובדי מטה מוצגת מולו להשוואה.'
    };

    const repKs = [{ id: 'all', label: 'כל המטבחים' }].concat(this.KITCHENS.map((x) => ({ id: x.id, label: x.name }))).map((r) => ({
      label: r.label, cls: s.repK === r.id ? 'on' : '', pick: () => this.setState({ repK: r.id })
    }));

    /* סקרים */
    const sMap = { open: ['פתוח לתגובות', 'pill p-ok'], closed: ['סגור', 'pill p-neu'], draft: ['טיוטה', 'pill p-low'] };
    const tMap = { draft: ['פרסם ופתח לתגובות', 'btn sm pri'], open: ['סגור את הסקר', 'btn sm'], closed: ['פתח מחדש', 'btn sm pri'] };
    const nextStatus = { draft: 'open', open: 'closed', closed: 'open' };
    /* הקישור מוביל לדף הסקר באתר (s.html). סקר שנוצר בדמו נושא את התוכן שלו אחרי # */
    const BUILTIN_SV = ['a7k2', 'm3p9', 'q8t1'];
    const svData = (v) => btoa(unescape(encodeURIComponent(JSON.stringify({ t: v.title, q: v.questions.map((q) => ({ type: q.type, q: q.q, options: q.options })) })))).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
    const linkOf = (v) => (typeof location !== 'undefined' ? location.origin : '') + '/s/' + v.code + (BUILTIN_SV.indexOf(v.code) < 0 ? '#' + svData(v) : '');
    const copyLink = (link) => {
      try {
        navigator.clipboard.writeText(link).then(() => this.flash('הקישור הועתק. אפשר להדביק אותו בוואטסאפ או במייל.'), () => this.flash('הקישור: ' + link));
