    };
    /* שליחה אישית בוואטסאפ: מספר ישראלי (050...) הופך לפורמט בינלאומי (97250...) */
    /* שליחה אוטומטית: תוכנת השליחה (whatsapp-sender) רצה במחשב ושולחת מהוואטסאפ המחובר */
    const WA_API = 'http://127.0.0.1:3001';
    const WA_ERR = {
      not_ready: 'תוכנת השליחה עוד לא מחוברת לוואטסאפ. פותחים את http://127.0.0.1:3001 וסורקים את הקוד.',
