            .finally(() => this.setState({ waBusy: false }));
        },
        sent: (cur2.sent || []).map((x) => ({ label: x.name + ' · ' + x.phone + ' · ' + x.at + (x.auto ? ' · אוטומטי' : '') })),
        hasSent: !!(cur2.sent || []).length,
        setTitle: (e) => { const val = e.target.value; this.updateSurvey(cur2.id, (x) => { x.title = val; return x; }); },
        setClose: (e) => { const val = e.target.value; this.updateSurvey(cur2.id, (x) => { x.closeDate = val; return x; }); },
        tabQ: 'tab' + (s.svTab === 'q' ? ' on' : ''), tabR: 'tab' + (s.svTab === 'r' ? ' on' : ''),
