        onQ: s.svTab === 'q', onR: s.svTab === 'r',
        noResp: cur2.responses === 0, results: cur2.responses === 0 ? [] : results,
        questions,
        addRating: addQ({ type: 'rating', q: 'שאלה חדשה', dist: [0, 0, 0, 0, 0] }),
        addChoice: addQ({ type: 'choice', q: 'שאלה חדשה', options: ['אפשרות 1', 'אפשרות 2'], counts: [0, 0] }),
        addText: addQ({ type: 'text', q: 'שאלה חדשה', answers: [] })
      });
