      { name: 'הגדרות התראה וניהול משתמשים', a: Y, b: N, c: N, d: N }
    ];

    const tabKeys = ['tasks', 'inv', 'exp', 'ord', 'rec', 'prod', 'chk'];
    const tab = {}, tabTo = {}, tabOn = {};
    tabKeys.forEach((t) => {
