    ['day', 'week', 'month'].forEach((p) => { per[p] = s.period === p ? 'on' : ''; perTo[p] = () => this.setState({ period: p }); });
    const navKeys = ['kitchens', 'menu', 'recipes', 'suppliers', 'invoices', 'reports', 'alerts', 'announce', 'surveys', 'users'];
