      wm, wq,
      recTabs, recipe, dishCost, pm,
      suppliers, addSup, priceRows, schedules,
      set,
      sim,
      alerts: { rows: aRows, exp: aExp, qty: aQty, price: aPrice, approve: aApprove, pl: plA.length, plStyle: plA.some((a) => a.level === 'red') ? 'color: #C62F4A' : plA.length ? 'color: #B5650A' : 'color: #037F4C' },
      trends, rm, sheetCmp,
      em, sw, sf,
      inv: { total: this.money(invTotal), waiting: invWaiting, gaps: invGaps },
      invRowsList,
      per, perTo, repKs,
      rep: {
        rev: this.money(rRev), cost: this.money(rCost), waste: this.money(rWaste),
        profit: this.money(rRev - rCost), profitStyle: this.plStyle(rRev - rCost), fc: this.pct(rCost / rRev),
        showKitchens: s.repK === 'all' && this.KITCHENS.length > 1,
        kbars, popular, wasteRows, plRows, rawRows,
        plSum: { out: plSum.out.toLocaleString('he-IL'), rev: this.money(plSum.rev), prepared: plSum.prepared.toLocaleString('he-IL'), cost: this.money(plSum.cost), profit: this.money(plSum.rev - plSum.cost), profitStyle: this.plStyle(plSum.rev - plSum.cost) },
        plRaw: this.money(rRaw), plRawNeg: '-' + this.money(rRaw), hasRaw: false,
        audName, rawNote: aud === 'all' ? '' : 'פחת חומרי גלם לא משויך לתפריט, ולכן הוא מוצג רק בתצוגת הכול.', hasRawNote: aud !== 'all',
        isDay: repPer === 'day', wkRows,
        wkSum: { stu: wkSum.stu.toLocaleString('he-IL'), stf: wkSum.stf.toLocaleString('he-IL'), meals: (wkSum.stu + wkSum.stf).toLocaleString('he-IL'), rev: this.money(wkSum.rev), cost: this.money(wkSum.cost), profit: this.money(wkSum.rev - wkSum.cost), profitStyle: this.plStyle(wkSum.rev - wkSum.cost, 'font-weight: 700; ') },
        wkTitle: 'שבוע עבודה · ' + this.HISTDAYS[0].label + '–' + this.HISTDAYS[this.HISTDAYS.length - 1].label,
        periodNote: { day: (repDay === this.HISTDAYS.length - 1 ? 'היום · ' : '') + this.HISTDAYS[repDay].label, week: 'שבוע עבודה, ראשון עד חמישי · ' + this.HISTDAYS[0].label + '–' + this.HISTDAYS[this.HISTDAYS.length - 1].label, month: 'חודש · ' + this.MONTH_DAYS + ' ימי עבודה לפי ממוצע השבוע' }[repPer]
      },
      sv,
      users, perms,
      newUser: () => this.flash('הוספת משתמש: שם ותפקיד. בדמו הכפתור לא פעיל.'),
      hasToast: !!s.toast,
      toast: s.toast
    };
  }
}
